window.SEARCH_DATA = [{"u": "./chapter_1.html#chapter-1__1", "c": "Chương 1", "k": "1", "n": 1, "q": "Tôi là người lao động của một công ty, hiện đang gặp vấn đề sức khoẻ và muốn đi khám bệnh. Tôi có thể khám, chữa bệnh ở đâu?", "a": "- Bạn có thể đến Phòng y tế của công ty hoặc Trung tâm chăm sóc sức khoẻ của khu công nghiệp để được cung cấp thông tin và tư vấn ban đầu. Ngoài ra, bạn cũng có thể đến Trạm Y tế xã/phường, hoặc các bệnh viện gần nơi làm việc (hoặc thuận tiện cho việc đi lại của bạn). Tại những cơ sở này, bạn sẽ được tư vấn về tình trạng sức khỏe và được hướng dẫn lựa chọn cơ sở khám chữa bệnh phù hợp. - Có rất nhiều cơ sở y tế mà bạn có thể đến khám như: Trạm y tế, bệnh viện đa khoa khu vực, phòng khám tư nhân, bệnh viện tư nhân, bệnh viện tỉnh hoặc bệnh viện trung ương gần nơi bạn đang làm việc, - Nếu bạn đến khám theo chế độ bảo hiểm, bạn cần mang theo thẻ bảo hiểm và các giấy tờ cần thiết (cụ thể ở phần sau)."}, {"u": "./chapter_1.html#chapter-1__2", "c": "Chương 1", "k": "1", "n": 2, "q": "Trước khi đi khám, nếu có thắc mắc, tôi có thể hỏi thông tin từ ai?", "a": "- Bạn có thể liên hệ với người phụ trách y tế cơ quan hoặc bộ phận nhân sự của công ty. Ngoài ra, bạn có thể đến cơ sở y tế gần nhất để hỏi thông tin. - Bạn có thể hỏi thêm người trong gia đình, các đồng nghiệp hoặc hàng xóm đã từng đi khám bệnh tại các cơ sở y tế uy tín (kinh nghiệm của những người đã từng đi khám/chữa bệnh rất quan trọng). - Tuỳ vào bạn đang ở địa phương nào, bạn có thể gọi điện trước đến cơ sở y tế để được hướng dẫn cụ thể. Việc gọi điện trước khi đến khám bệnh giúp bạn chuẩn bị đầy đủ giấy tờ cần thiết và tiết kiệm thời gian đi khám. Bạn có thể gọi điện hoặc đến Trung tâm chăm sóc sức khoẻ/phòng y tế KCN để có thông tin cần thiết. - Một cách nữa là bạn có thể vào trang mạng (Website) chính thống của các bệnh viện gần nhất để có thêm thông tin trước khi đến khám bệnh. LƯU Ý : Khi bạn hoặc người trong gia đình bị ốm, nên đến cơ sở y tế gần nhất để được tư vấn và khám bệnh kịp thời, đây là cách hiệu quả và an toàn nhất. Dựa trên các thông tin có được, bạn cần cân nhắc lựa chọn cơ sở y tế phù hợp với hoàn cảnh cá nhân, gia đình và quan trọng là cơ sở đó phải đảm bảo uy tín."}, {"u": "./chapter_1.html#chapter-1__3", "c": "Chương 1", "k": "1", "n": 3, "q": "Khi đi khám, tôi cần mang theo giấy tờ gì?", "a": "- Các giấy tờ bạn cần mang theo (đối với tất cả mọi người) bao gồm: Căn cước công dân (giấy tờ tuỳ thân), thẻ bảo hiểm (hiện đã có thẻ bảo hiểm điện tử, tuy nhiên có thể bệnh viện sẽ yêu cầu đối chiếu, kiểm tra thông tin trên thẻ). - Nếu đã từng khám bệnh: Sổ khám bệnh, các kết quả xét nghiệm và chẩn đoán bệnh của lần khám bệnh gần nhất; đơn thuốc của lần điều trị trước hoặc đơn thuốc đang điều trị (đặc biệt quan trọng nếu bệnh có triệu chứng tương tự như lần ốm này). Nếu có giấy hẹn khám của lần khám trước, bạn cần mang theo để thuận tiện cho việc thăm khám. - Nếu là chuyển viện thì cần có giấy chuyển tuyến và các giấy tờ của bệnh viện chuyển đi. LƯU Ý : Nếu có thể, hãy gọi điện trước đến bệnh viện/cơ sở y tế bạn dự định đến khám để hỏi các thủ tục và giấy tờ cần mang theo. Việc này giúp tránh việc thiếu giấy tờ mất thời gian đi lại nhiều lần, bởi mỗi cơ sở y tế có thể yêu cầu thêm một số loại giấy tờ khác các loại giấy tờ đã nêu trên)."}, {"u": "./chapter_1.html#chapter-1__4", "c": "Chương 1", "k": "1", "n": 4, "q": "Nếu tôi được chẩn đoán mắc bệnh mà cần phải nằm viện điều trị, tôi sẽ phải làm gì?", "a": "- Nếu bệnh cần điều trị, bạn sẽ được chỉ định nhập viện để điều trị nội trú. - Sau khi khám và làm các xét nghiệm, nhân viên y tế sẽ hướng dẫn bạn cụ thể về qui trình nhập viện, các thủ tục cần làm, và tương tự khi được xuất viện bạn sẽ được hướng dẫn đầy đủ. Lưu ý, mỗi bệnh viện có thể qui trình tiếp nhận và hướng dẫn khác nhau, nên bạn cần tuân thủ theo hướng dẫn của nhân viên y tế và bác sĩ tại bệnh viện đó."}, {"u": "./chapter_1.html#chapter-1__5", "c": "Chương 1", "k": "1", "n": 5, "q": "Nếu bệnh tình của tôi không tiến triển, tôi có thể chuyển sang điều trị tại một bệnh viện hoặc cơ sở y tế khác không?", "a": "- Trong trường hợp tình trạng bệnh không tiến triển, bạn có thể được bác sĩ chỉ định hoặc giới thiệu sang một bệnh viện khác có chuyên môn cao hơn. Bạn cũng có thể tự đề nghị được chuyển sang bệnh viện hoặc cơ sở y tế khác để tiếp tục điều trị. - Nếu được chuyển viện đúng tuyến (bệnh viện tuyến giới thiệu lên bệnh viện đúng tuyến): bạn sẽ được hưởng chế độ bảo hiểm y tế đầy đủ theo qui định. - Nếu chuyển đến bệnh viện không đúng tuyến (thường theo yêu cầu của bạn hoặc đến bệnh viện chuyên khoa): bạn vẫn được hưởng bảo hiểm y tế, tuy nhiên mức hưởng có thể thấp hơn so với mức khi chuyển đúng tuyến."}, {"u": "./chapter_1.html#chapter-1__6", "c": "Chương 1", "k": "1", "n": 6, "q": "Tôi cần làm gì để được chuyển viện?", "a": "- Để được chuyển viện, bạn cần có: Giấy chuyển viện cùng các hồ sơ, giấy tờ và kết quả xét nghiệm do cơ sở y tế bạn đang điều trị cung cấp. - Trước khi nhận giấy chuyển viện, bạn cần thực hiện các nghĩa vụ với bệnh viện như: thanh toán viện phí, trả đồ đã mượn (quần, áo, đồ dùng….). Trong trường hợp tự đề nghị chuyển viện, bạn có thể phải viết đơn cam kết chịu trách nhiệm. - Phương tiện vận chuyển, nếu sử dụng xe cấp cứu của bệnh viện, chi phí thường phải thanh toán riêng và không nằm trong gói bảo hiểm y tế. Bạn có thể thuê phương tiện vận chuyển ngoài bệnh viện nếu muốn. LƯU Ý : Thủ tục chuyển viện cần tuân theo hướng dẫn của bệnh viện bạn đang nằm điều trị."}, {"u": "./chapter_1.html#chapter-1__7", "c": "Chương 1", "k": "1", "n": 7, "q": "Làm thế nào để mua thuốc? Tôi có thể mua thuốc trực tiếp tại nhà thuốc, trên website hoặc ứng dụng di động mà không cần đơn thuốc của bác sĩ được không?", "a": "- Để mua thuốc, thông thường bạn cần có đơn thuốc của bác sĩ. Tuy nhiên, một số loại thuốc không cần kê đơn vẫn có thể mua trực tiếp. Lời khuyên: Với các loại thuốc điều trị bệnh, bạn nên có đơn thuốc của bác sĩ, hoặc ít nhất theo lời khuyên của nhân viên bán thuốc (đối với các bệnh nhẹ thông thường). - Bạn có thể mua một số loại thuốc không cần đơn của bác sĩ từ các cửa hàng bán thuốc hoặc đặt hàng trên mạng. Tuy nhiên, nếu không mua theo đơn thuốc của bác sĩ, thì việc bạn dùng thuốc sai qui định, sai liều hoặc ảnh hưởng đến tính mạng sẽ không có người chịu trách nhiệm."}, {"u": "./chapter_1.html#chapter-1__8", "c": "Chương 1", "k": "1", "n": 8, "q": "Tôi thấy trên các trang mạng xã hội như Facebook và YouTube có nhiều quảng cáo về các phương pháp chữa bệnh, gồm cả thuốc tây y và đông y. Tôi có nên tin tưởng và liên hệ với những nguồn thông tin này không?", "a": "Bạn chỉ nên liên hệ nếu các trang mạng là của các cơ sở y tế chính thống. Với những nguồn tin không rõ ràng, bạn cần hết sức thận trọng trước khi sử dụng dịch vụ hay mua thuốc. Bạn nên gọi điện theo số điện thoại trên trang mạng để kiểm chứng thông tin. CẢNH BÁO: Nếu mua thuốc hoặc làm theo hướng dẫn từ các trang mạng không đáng tin cậy, bạn sẽ khó xác định trách nhiệm khi xảy ra rủi ro (thuốc giả, thuốc kém chất lượng hoặc hướng dẫn điều trị bệnh sai…). Hiện nay, có nhiều trang mạng lừa đảo tinh vi mà bạn rất khó có thể nhận biết."}, {"u": "./chapter_1.html#chapter-1__9", "c": "Chương 1", "k": "1", "n": 9, "q": "Tôi từ nơi khác tới làm việc và có ký hợp đồng lao động với công ty. Vậy sau bao lâu làm việc tại công ty thì tôi được đóng BHXH bắt buộc?", "a": "Người làm việc theo hợp đồng lao động không xác định thời hạn, hợp đồng lao động xác định thời hạn có thời hạn từ đủ 01 tháng trở lên đều thuộc diện tham gia BHXH bắt buộc. Trường hợp người lao động và người sử dụng lao động thỏa thuận bằng tên gọi khác nhưng có nội dung thể hiện về việc làm có trả công, tiền lương và chịu sự quản lý, điều hành, giám sát của một bên thì vẫn thuộc đối tượng tham gia BHXH bắt buộc."}, {"u": "./chapter_1.html#chapter-1__10", "c": "Chương 1", "k": "1", "n": 10, "q": "Tôi có được đăng ký tham gia bảo hiểm xã hội bắt buộc và bảo hiểm thất nghiệp không? Nếu được thì ai sẽ đăng ký cho tôi và số tiền tôi phải đóng hàng tháng được tính như thế nào?", "a": "• Bạn thuộc đối tượng tham gia BHXH bắt buộc và bảo hiểm thất nghiệp. Việc đăng ký tham gia bảo hiểm sẽ do người sử dụng lao động (chủ doanh nghiệp, Giám đốc công ty, người thuê bạn làm việc) thực hiện cho bạn theo mức đóng bảo hiểm qui định hiện hành. • Theo qui định của Luật Bảo hiểm mới nhất (Điều 33, 34 luật BHXH năm 2024, và điều 9 Nghị quyết số 158/2025/NĐ-CP), có hiệu lực từ ngày 01/7/2025), mức đóng BHXH được tính theo mức lương như sau: người lao động đóng ít nhất 8% vào quỹ hưu trí và tử tuất; người sử dụng lao động đóng ít nhất 17% vào quĩ ốm đau, thai sản và quỹ hưu trí, tử tuất."}, {"u": "./chapter_1.html#chapter-1__11", "c": "Chương 1", "k": "1", "n": 11, "q": "Tôi có thể kiểm tra bằng cách nào để biết mình đã được công ty đăng ký tham gia BHXH bắt buộc và bảo hiểm thất nghiệp hay chưa, cũng như việc đóng bảo hiểm đã đúng và đủ hay không?", "a": "• Bạn có thể hỏi người/phòng/ban làm công tác nhân sự của công ty. • Bạn có thể tra cứu mã số BHXH trên Cổng thông tin điện tử BHXH Việt Nam ”baohiemxahoi.gov.vn” tại mục “Tra cứu”. • Khi đã có mã số BHXH, bạn nên sử dụng ứng dụng VssID và đăng nhập bằng tài khoản định danh điện tử để theo dõi quá trình tham gia và đóng bảo hiểm của mình."}, {"u": "./chapter_1.html#chapter-1__12", "c": "Chương 1", "k": "1", "n": 12, "q": "Công ty đã đăng ký cho tôi tham gia BHXH bắt buộc. Vậy tôi có thể hưởng các chế độ, trợ cấp như thế nào và các chế độ đó bao gồm những gì?", "a": "• Theo qui định của luật Bảo hiểm xã hội, người lao động có những quyền lợi khi tham gia bảo hiểm xã hội bắt buộc được hưởng 5 chế độ tương ứng với 5 quyền lợi: (1) khi ốm đau, (2) thai sản, (3) tai nạn lao động - bệnh nghề nghiệp, (4) hưu trí và (5) tử tuất. Bảng 1.3 Các quyền lợi cụ thể khi người lao động tham gia BHXH bắt buộc: Quyền lợi BHXH khi ốm đau, bệnh tật Quyền lợi BHXH khi mang thai và sinh con Quyền lợi BHXH khi tai nạn lao động, mắc bệnh nghề nghiệp Quyền lợi BHXH khi về hưu Quyền lợi BHXH khi mất (tử tuất)."}, {"u": "./chapter_1.html#chapter-1__13", "c": "Chương 1", "k": "1", "n": 13, "q": "Trong trường hợp người lao động gặp tai nạn giao thông nghiêm trọng, họ có được bảo hiểm xã hội bắt buộc chi trả không?", "a": "Nếu người lao động bị tai nạn giao thông khi đang làm nhiệm vụ của công ty, trên tuyến đường hợp lý đi từ nhà đến nơi làm việc và ngược lại, khi vào bệnh viện cấp cứu và điều trị sẽ được hưởng chế độ của Bảo hiểm y tế (nếu đã tham gia bảo hiểm theo quy định)."}, {"u": "./chapter_1.html#chapter-1__14", "c": "Chương 1", "k": "1", "n": 14, "q": "Tôi là người lao động đã làm việc và tham gia đóng BHXH bắt buộc tại công ty được 15 năm. Do vấn đề sức khỏe, tôi không thể tiếp tục làm việc. Vậy tôi có thể nghỉ việc không? Nếu nghỉ việc, tôi có được hưởng chế độ bảo hiểm tương ứng với thời gian đã đóng trong 15 năm qua không?", "a": "• Bạn có thể nghỉ việc mà không bị mất quyền lợi bảo hiểm đã tham gia. • Bạn được hưởng chế độ bảo hiểm (lương hưu) do đã đóng BHXH trong 15 năm (Theo Luật Bảo hiểm sửa đổi năm 2025, bắt đầu áp dụng từ 01/7/2025 qui định giảm điều kiện về số năm đóng BHXH tối thiểu để được hưởng lương hưu hàng tháng từ 20 năm xuống 15 năm). Bạn tham khảo Bảng 1.4. dưới đây để biết thêm về thông tin chế độ rút bảo hiểm 1 lần). • Bạn nên liên hệ với bộ phận nhân sự của công ty để biết rõ qui định của công ty về các điều khoản, điều kiện và cách tính toán mức được hưởng bảo hiểm liên quan đến việc này. Bảng 1.4 Quy định về rút BHXH một lần Luật Bảo hiểm xã hội (sửa đổi) đã được Quốc hội thông qua tại Kỳ họp thứ 7 Quốc hội khóa XV. Theo đó, quy định về việc người lao động được rút BHXH 1 lần có một số sự điều chỉnh. Điều kiện để được rút BHXH một lần sau khi điều chỉnh là: • Người lao động có thời gian đóng BHXH trước ngày Luật Bảo hiểm xã hội (sửa đổi) có hiệu lực thi hành (ngày 01/7/2025). • Đã chấm dứt việc tham gia BHXH. • Sau 12 tháng không thuộc đối tượng tham gia BHXH bắt buộc mà cũng không tham gia BHXH tự nguyện. • Có thời gian đóng BHXH chưa đủ 20 năm. • Có đề nghị được hưởng BHXH một lần. Dựa theo các điều kiện trên, việc rút BHXH một lần vẫn được duy trì với người lao động đã, đang và sẽ tham gia đóng BHXH bắt buộc trước ngày 01/7/2025, nghĩa là dù cho người lao động mới bắt đầu tham gia BHXH từ ngày 30/6/2025 thì vẫn được rút BHXH một lần nếu đủ các điều kiện kể trên. Người tham gia BHXH từ ngày 01/7/2025 vẫn sẽ được rút BHXH một lần trong một số trường hợp đặc biệt như: • Đủ tuổi hưởng lương hưu mà chưa đủ 15 năm đóng BHXH. • Ra nước ngoài để định cư. • Người mắc các bệnh như: ung thư, bại liệt, xơ gan mất bù, lao nặng, AIDS. • Người bị suy giảm khả năng lao động từ 81% trở lên. • Người khuyết tật đặc biệt nặng… Chỉ có trường hợp người lao động sau 12 tháng nghỉ việc, không tham gia BHXH và có thời gian đóng BHXH chưa đủ 20 năm thì không được rút BHXH một lần nữa. Quy định về rút Bảo hiểm xã hội một lần: Luật Bảo hiểm xã hội (sửa đổi) đã được Quốc hội thông qua tại Kỳ họp thứ 7 Quốc hội khóa XV, theo đó, quy định về việc người lao động được rút BHXH 1 lần có một số sự điều chỉnh. Điều kiện để được rút BHXH một lần sau khi điều chỉnh là: Đã chấm dứt việc tham gia BHXH Sau 12 tháng không thuộc đối tượng tham gia BHXH bắt buộc mà cũng không tham gia BHXH tự nguyện Có thời gian đóng BHXH chưa đủ 20 năm Có đề nghị được hưởng BHXH một lần Dựa theo các điều kiện trên, việc rút BHXH một lần vẫn được duy trì với người lao động đã, đang và sẽ tham gia đóng BHXH bắt buộc trước ngày 01/7/2025, nghĩa là dù cho người lao động mới bắt đầu tham gia BHXH từ ngày 30/6/2025 thì vẫn được rút BHXH một lần nếu đủ các điều kiện kể trên. Người tham gia BHXH từ ngày 01/7/2025 vẫn sẽ được rút BHXH một lần trong một số trường hợp đặc biệt như: • Đủ tuổi hưởng lương hưu mà chưa đủ 15 năm đóng BHXH • Ra nước ngoài để định cư • Người đang mắc một trong những bệnh ung thư, bại liệt, xơ gan mất bù, lao nặng, AIDS • Người bị suy giảm khả năng lao động từ 81% trở lên • Người khuyết tật đặc biệt nặng… Chỉ có trường hợp người lao động sau 12 tháng nghỉ việc, không tham gia BHXH và có thời gian đóng BHXH chưa đủ 20 năm thì không được rút BHXH một lần nữa."}, {"u": "./chapter_1.html#chapter-1__15", "c": "Chương 1", "k": "1", "n": 15, "q": "Nếu tôi bị bệnh ung thư vú, tôi được hưởng quyền lợi gì từ các loại bảo hiểm bắt buộc?", "a": "• Theo quy định, bạn sẽ được hưởng các chế độ từ BHXH khi ốm đau. Tuy nhiên mức hưởng bảo hiểm còn phụ thuộc vào cơ sở y tế bạn đến điều trị (đúng tuyến hay trái tuyến, bệnh viện trung ương hay địa phương). Đối với người bệnh ung thư, quyền lợi bảo hiểm còn phụ thuộc vào loại thuốc điều trị (có loại thuốc được bảo hiểm chi trả hoàn toàn, có loại chỉ được trả một phần, có loại bạn phải tự trả 100%). Bạn tìm hiểu kỹ về bảo hiểm đối với trường hợp cụ thể của bạn tại cơ sở y tế điều trị. • Bạn có thể được hưởng bảo hiểm: Phí khám bệnh, các xét nghiệm cơ bản, thuốc điều trị ung thư (nếu trong danh mục được hưởng bảo hiểm), tiền giường nằm, thuốc điều trị đi kèm (trong danh mục được hưởng bảo hiểm). • Trước khi quyết định liệu trình điều trị ung thư cho bạn, bác sĩ hoặc nhân viên phụ trách bảo hiểm của bệnh viện sẽ tư vấn cụ thể để có liệu trình điều trị phù hợp với điều kiện kinh tế của bạn và các thủ tục để được hưởng bảo hiểm."}, {"u": "./chapter_1.html#chapter-1__16", "c": "Chương 1", "k": "1", "n": 16, "q": "Tôi đã ký hợp đồng lao động không xác định thời hạn với công ty, vậy tôi có được đóng bảo hiểm y tế bắt buộc không? Ai là người đóng, tôi hay công ty?", "a": "Bạn thuộc đối tượng phải tham gia các loại bảo hiểm bắt buộc trong đó có bảo hiểm y tế. Các loại bảo hiểm bắt buộc được đóng bởi người lao động và công ty sử dụng người lao động. Hàng tháng, công ty sẽ trích một phần lương của bạn, đồng thời đóng thêm phần trách nhiệm công ty để tham gia các loại bảo hiểm bắt buộc cho người lao động, bao gồm cả bảo hiểm y tế."}, {"u": "./chapter_1.html#chapter-1__17", "c": "Chương 1", "k": "1", "n": 17, "q": "Nếu tôi bị ốm và muốn đi khám bệnh, tôi cần làm gì để có thể sử dụng thẻ bảo hiểm y tế tại các cơ sở y tế? Những dịch vụ y tế nào sẽ được bảo hiểm y tế chi trả?", "a": "• Bạn nên đến khám tại các cơ sở y tế nhà nước sẽ được hưởng bảo hiểm y tế. Một số cơ sở y tế tư nhân cũng có khám bệnh theo bảo hiểm y tế (bạn nên tìm hiểu và hỏi rõ trước khi đến khám). • Mức hưởng bảo hiểm y tế được qui định rõ tùy theo việc bạn khám đúng tuyến hay trái tuyến, tại cơ sở y tế tuyến trung ương, tuyến tỉnh hoặc trạm y tế xã. • Quy định quyền lợi hưởng bảo hiểm y tế được trình bày trong Bảng 1.5 dưới đây. Bảng 1.5 BẢO HIỂM Y TẾ BẮT BUỘC (Luật Bảo hiểm y tế mới sửa đổi áp dụng từ 01/01/2025 Số: 01 /2025/TT-BYT) Bảo hiểm y tế là một hình thức bảo vệ sức khỏe và an toàn cho người dân khi gặp phải các rủi ro về sức khỏe, bệnh tật, tai nạn. Người tham gia bảo hiểm y tế sẽ được hưởng nhiều quyền lợi khi đi khám chữa bệnh như sau: ĐƯỢC CẤP THẺ BẢO HIỂM Y TẾ: Đây là giấy tờ chứng minh quyền lợi của người tham gia bảo hiểm y tế. Thẻ bảo hiểm y tế có giá trị sử dụng trên toàn quốc và được cấp miễn phí cho người tham gia. ĐƯỢC LỰA CHỌN CƠ SỞ KHÁM CHỮA BỆNH BAN ĐẦU: Người tham gia có quyền tự chọn cơ sở khám chữa bệnh ban đầu theo nhu cầu và điều kiện của mình. Cơ sở khám chữa bệnh ban đầu là nơi người tham gia đăng ký khám chữa bệnh đầu tiên trong năm. ĐƯỢC KHÁM CHỮA BỆNH: Người tham gia bảo hiểm y tế có quyền được khám chữa bệnh theo các dịch vụ trong danh mục của Bộ Y tế. Người tham gia có thể khám chữa bệnh ở cơ sở khám chữa bệnh ban đầu hoặc được chuyển tuyến theo chỉ định của bác sĩ. ĐƯỢC THANH TOÁN CHI PHÍ KHÁM CHỮA BỆNH THEO CHẾ ĐỘ BẢO HIỂM Y TẾ: Người tham gia bảo hiểm y tế có quyền được thanh toán chi phí khám chữa bệnh từ Quỹ Bảo hiểm y tế theo các mức hưởng khác nhau tuỳ thuộc vào loại hình dịch vụ, loại hình người tham gia và loại hình khám chữa bệnh. Mức hưởng có thể từ 40% đến 100% chi phí khám chữa bệnh. ĐƯỢC GIẢI THÍCH, CUNG CẤP THÔNG TIN, KHIẾU NẠI, TỐ CÁO HÀNH VI VI PHẠM PHÁP LUẬT VỀ BẢO HIỂM Y TẾ: Người tham gia bảo hiểm y tế có quyền được giải thích, cung cấp thông tin về các quy định, quy trình, biểu mẫu liên quan đến việc thực hiện quyền lợi của mình. Người tham gia cũng có quyền khiếu nại, tố cáo các hành vi vi phạm pháp luật về bảo hiểm y tế của các tổ chức, cá nhân liên quan."}, {"u": "./chapter_1.html#chapter-1__18", "c": "Chương 1", "k": "1", "n": 18, "q": "(Chị Ngọc, 29 tuổi): Tôi đã đi khám bệnh bác sĩ chẩn đoán bị viêm phổi và chỉ định tôi vào viện điều trị nội trú (theo bác sĩ nói tôi sẽ nằm viện 5-7 ngày). Tôi muốn biết những dịch vụ y tế nào khi điều trị nội trú được bảo hiểm y tế chi trả?", "a": "• Trường hợp của chị Ngọc được hưởng bảo hiểm y tế. Để biết chính xác mức hưởng, bạn nên hỏi bộ phận tiếp nhận bảo hiểm tại cơ sở y tế nơi khám, chữa bệnh để được hướng dẫn cụ thể. Mức được hưởng bảo hiểm theo qui định của Luật Bảo hiểm y tế mới sửa đổi và áp dụng từ 01/01/2025. • Thông thường bảo hiểm chi trả cho dịch vụ: Khám bệnh; các xét nghiệm cơ bản, chụp chiếu tim phổi, siêu âm ổ bụng; thuốc điều trị và giường nằm trong thời gian điều trị nội trú. Một số bệnh có thể được yêu cầu các xét nghiệm và chẩn đoán hình ảnh ngoài danh mục bảo hiểm mà không được chi trả. Mục nào bảo hiểm chi trả và mục nào không được chi trả được làm rất rõ trong giấy chỉ định xét nghiệm và hoá đơn thanh toán các dịch vụ tại bệnh viện."}, {"u": "./chapter_1.html#chapter-1__19", "c": "Chương 1", "k": "1", "n": 19, "q": "Nếu có thắc mắc hay cần giải thích về bảo hiểm y tế thì tôi nên liên hệ với ai?", "a": "Bạn có thể biết rõ hơn thông tin về bảo hiểm từ các nguồn thông tin sau: • Người/phòng/ban làm công tác nhân sự của công ty; nhân viên tiếp nhận bảo hiểm tại các cơ sở y tế. • Nhân viên bảo hiểm tại các bệnh viện. Các bệnh viện thường có quầy giao dịch dành cho người bệnh khám chữa bệnh bảo hiểm. • Tại Trạm y tế xã, nên hỏi bác sĩ phụ trách trạm. • Nếu có điều kiện và thời gian, bạn cũng có thể tham khảo thêm về Luật Bảo hiểm y tế."}, {"u": "./chapter_1.html#chapter-1__20", "c": "Chương 1", "k": "1", "n": 20, "q": "(Anh Thọ, 35 tuổi): Hiện tại tôi đang điều trị nội trú cho chứng đau lưng ở bệnh viện, nhưng tình trạng bệnh không thuyên giảm và được bác sĩ chỉ định chuyển đến một bệnh viện khác. Trong trường hợp này bảo hiểm y tế có tiếp tục chi trả chi phí chữa bệnh sau khi tôi chuyển đến bệnh viện khác không?", "a": "Bạn vẫn được hưởng bảo hiểm y tế nếu chuyển đến các bệnh viện có chi trả bảo hiểm y tế. Tuy nhiên, tuỳ theo bệnh viện bạn chuyển đến sẽ có tỉ lệ chi trả khác nhau (theo phân cấp mới nhất của Bộ Y tế). Tại bệnh viên, bạn hỏi thông tin cụ thể về mức hưởng bảo hiểm và cần có giấy chuyển tuyến."}, {"u": "./chapter_1.html#chapter-1__21", "c": "Chương 1", "k": "1", "n": 21, "q": "Tôi là lao động nữ đang làm việc cho một công ty, đã tham gia BHXH bắt buộc và bảo hiểm y tế, hiện đang mang thai. Nếu sinh con ở bệnh viện công lập, tôi sẽ được bảo hiểm chi trả như thế nào?", "a": "• Bảo hiểm y tế sẽ chi trả 80-100% cho việc sinh con nếu bạn sinh tại các bệnh viện công lập, cơ sở khám chữa bệnh khám chữa bệnh đúng tuyến. Một số bệnh viện tư có thể được thanh toán bảo hiểm y tế nếu có ký hợp đồng với cơ quan bảo hiểm y tế. • Dựa vào mã số thẻ bảo hiểm y tế của từng cá nhân ( từ số 1 đến 5) mà có mức hưởng khác nhau: 80%, 95% và 100%."}, {"u": "./chapter_1.html#chapter-1__22", "c": "Chương 1", "k": "1", "n": 22, "q": "Mức hưởng bảo hiểm sinh con tại bệnh viện trái tuyến và bệnh viện tư có khác nhau không?", "a": "• Nếu bạn sinh con tại cơ sở y tế trái tuyến sẽ được thanh toán theo mức hưởng quy định đối với trường hợp sinh con đúng tuyến như trên theo tỷ lệ: 40%-100% tuỳ theo cơ sở y tế. • Nếu bạn sinh con tại các bệnh viện tư nhân thì sẽ tuỳ theo chính sách bảo hiểm để được hưởng như bảo hiểm trái tuyến. Nếu bệnh viện tư không áp dụng chế độ thanh toán bảo hiểm, bạn sẽ không được thanh toán. (Bạn nên tham khảo kỹ về quyền lợi bảo hiểm tại các cơ sở y tế trước khi đăng ký sinh con)."}, {"u": "./chapter_1.html#chapter-1__23", "c": "Chương 1", "k": "1", "n": 23, "q": "Chị Ngọc (29 tuổi, công nhân may tại Bắc Ninh, có hai con nhỏ). Chị Ngọc muốn biết quyền lợi của lao động nữ khi có con nhỏ.", "a": "• Người lao động nữ trong thời gian nuôi con dưới 12 tháng tuổi được nghỉ 60 phút/ngày trong thời gian làm việc để cho con bú, vắt, trữ sữa, nghỉ ngơi. Như vậy, bạn được nghỉ 60 phút mỗi ngày để cho con bú, vắt sữa hoặc nghỉ ngơi. Bạn có thể chọn 60 phút nghỉ vào thời điểm thích hợp trong ngày để phù hợp với công việc của công ty và việc chăm sóc con. • Con lớn 5 tuổi của bạn có thể gửi học trường mẫu giáo tại địa phương nơi bạn sinh sống hoặc nhà gửi trẻ của công ty (nếu có). Một số công ty có thể hỗ trợ chi phí gửi trẻ cho con trong độ tuổi gửi nhà trẻ, mẫu giáo nếu không tổ chức nơi trông giữ trẻ. Tuy nhiên, mức hỗ trợ này không qui định mà tuỳ thuộc vào chính sách của từng công ty."}, {"u": "./chapter_2.html#chapter-2__1", "c": "Chương 2", "k": "2", "n": 24, "q": "Tôi có thể yêu cầu công ty luôn cung cấp đầy đủ găng tay bảo hộ lao động không?", "a": "Có, bạn hoàn toàn có quyền yêu cầu công ty phải luôn cung cấp đầy đủ găng tay và các thiết bị bảo hộ lao động cần thiết khi làm việc với hóa chất. Đây là quyền lợi chính đáng của người lao động và được pháp luật bảo vệ."}, {"u": "./chapter_2.html#chapter-2__2", "c": "Chương 2", "k": "2", "n": 25, "q": "Tôi làm trong một công ty cơ khí, bị ô nhiễm tiếng ồn với cường độ cao. Tôi nên làm gì để bảo vệ được bản thân và những người lao động khác tránh được tiếng ồn?", "a": "Môi trường làm việc trong công ty cơ khí thường xuyên bị ô nhiễm tiếng ồn với cường độ cao, bạn và các người lao động khác có nguy cơ bị ảnh hưởng nghiêm trọng đến sức khỏe, đặc biệt là thính giác. Dưới đây là những việc bạn nên làm để bảo vệ bản thân và đồng nghiệp khỏi tác hại của tiếng ồn: 1) Sử dụng đầy đủ phương tiện bảo vệ cá nhân như nút tai, chụp tai chống ồn khi làm việc. 2) Tham gia tập huấn an toàn, vệ sinh lao động, nâng cao ý thức tự bảo vệ. 3) Yêu cầu khám sức khỏe định kỳ, đặc biệt là kiểm tra thính lực. 4) Báo cáo kịp thời nguy cơ rủi ro do tiếng ồn với người quản lý hoặc bộ phận an toàn. 5) Kiến nghị doanh nghiệp đánh giá, đo đạc mức tiếng ồn định kỳ, nếu vượt ngưỡng cho phép thì phải có biện pháp giảm thiểu phù hợp."}, {"u": "./chapter_2.html#chapter-2__3", "c": "Chương 2", "k": "2", "n": 26, "q": "Tôi có thể được cung câp thông tin rõ ràng về qui định an toàn lao động (ATLĐ) và trách nhiệm của doanh nghiệp khi bắt đầu làm việc ở một công ty không?", "a": "Khi bắt đầu làm việc ở một công ty, bạn có quyền và nghĩa vụ tìm hiểu kỹ các quy định và trách nhiệm của doanh nghiệp về ATLĐ. Điều này không chỉ để bảo vệ bản thân bạn mà còn để đảm bảo sự an toàn cho tập thể. Những quy định này bao gồm: 1) Đào tạo ATLĐ ban đầu khi vào công ty *Người lao động mới phải được tập huấn về an toàn, vệ sinh lao động trước khi bắt đầu làm việc. *Nội dung gồm: +Nhận biết các nguy cơ, rủi ro trong công việc. +Hướng dẫn sử dụng thiết bị bảo hộ cá nhân. +Quy trình xử lý sự cố hoặc tai nạn lao động. +Nội quy, quy trình vận hành an toàn tại nơi làm việc. 2) Cung cấp và sử dụng thiết bị bảo hộ *Công ty phải trang bị đầy đủ phương tiện bảo hộ lao động phù hợp (như mũ, găng tay, kính, khẩu trang...). *Người lao động có trách nhiệm sử dụng đúng cách các thiết bị này. 3) Người lao động cần tuân thủ nội quy và hướng dẫn an toàn *Phải làm việc đúng quy trình kỹ thuật. *Không tự ý vận hành máy móc nếu chưa được hướng dẫn. *Không làm việc khi không đảm bảo sức khỏe, hoặc trong tình trạng say rượu, mệt mỏi. 4) Báo cáo kịp thời khi có nguy hiểm *Nếu phát hiện nguy cơ mất an toàn, người lao động phải báo ngay cho quản lý hoặc bộ phận an toàn. *Có trách nhiệm tham gia cứu nạn hoặc sơ tán nếu được yêu cầu. 5) Khám sức khỏe và hồ sơ y tế: Một số ngành nghề yêu cầu người lao động khám sức khỏe định kỳ hoặc trước khi làm việc."}, {"u": "./chapter_2.html#chapter-2__4", "c": "Chương 2", "k": "2", "n": 27, "q": "Khi làm việc theo hợp đồng lao động, tôi có được tham gia đào tạo hoặc huấn luyện về an toàn lao động không?", "a": "- Bạn có được tập huấn về An toàn lao động. - Theo Điều 17 của Luật An toàn, vệ sinh lao động năm 2015, người lao động phải được huấn luyện An toàn lao động trước khi làm việc, khi chuyển công việc hoặc khi có thiết bị, công nghệ mới. - Doanh nghiệp có trách nhiệm tổ chức tập huấn định kỳ để người lao động nhận biết nguy cơ, phòng ngừa tai nạn lao động và bệnh nghề nghiệp."}, {"u": "./chapter_2.html#chapter-2__5", "c": "Chương 2", "k": "2", "n": 28, "q": "Tôi đang làm việc theo hợp đồng lao động. Nếu trong quá trình làm việc xảy ra tai nạn bị thương nặng thì tôi nên làm gì? Tôi nên liên hệ với ai để được hỗ trợ?", "a": "Nếu bạn bị tai nạn lao động, những việc cần làm ngay: • Báo ngay cho người sử dụng lao động (quản lý trực tiếp, tổ trưởng, hoặc bộ phận nhân sự). • Yêu cầu đưa đi cấp cứu kịp thời tại cơ sở y tế gần nhất. • Liên hệ với Công đoàn cơ sở (nếu có) để được hỗ trợ. • Ghi nhận lại bằng chứng (nếu có) để phục vụ việc giám định tai nạn sau này. • Người sử dụng lao động có trách nhiệm báo cáo tai nạn lao động với cơ quan chức năng theo quy định tại Điều 34 Luật An toàn, vệ sinh lao động 2015."}, {"u": "./chapter_2.html#chapter-2__6", "c": "Chương 2", "k": "2", "n": 29, "q": "Nếu tôi bị tai nạn lao động tại nơi làm việc và phải nhập viện điều trị, tôi sẽ được hưởng những hỗ trợ gì? Chi phí điều trị sẽ do ai chi trả?", "a": "Bạn sẽ nhận được hỗ trợ từ công ty nơi bạn làm việc, Theo Điều 38 và 39 Luật An toàn, vệ sinh lao động 2015: • Người sử dụng lao động phải chi trả toàn bộ chi phí y tế sơ cấp cứu, điều trị ban đầu. • Nếu bạn tham gia bảo hiểm tai nạn lao động (qua BHXH bắt buộc), bạn sẽ được: • Chi trả chi phí y tế theo qui định. • Trợ cấp tai nạn lao động (một lần hoặc hàng tháng tùy mức độ suy giảm khả năng lao động). • Phục hồi chức năng nếu có yêu cầu. • Nếu chi phí điều trị vượt quá mức được bảo hiểm y tế chi trả, người lao động sẽ phải tự thanh toán phần chi phí còn lại. • Trong một số trường hợp, tùy theo chính sách của từng công ty, người sử dụng lao động có thể hỗ trợ thêm một phần chi phí này, nhưng điều đó không phải là nghĩa vụ bắt buộc."}, {"u": "./chapter_2.html#chapter-2__7", "c": "Chương 2", "k": "2", "n": 30, "q": "Trong trường hợp tôi bị ốm đau hoặc tai nạn lao động, tôi có được nghỉ việc và hưởng chế độ có lương không?", "a": "• Nếu bạn phải nghỉ làm để điều trị và phục hồi do tai nạn lao động, người sử dụng lao động có trách nhiệm trả đủ lương trong thời gian này theo quy định tại Điều 38 Luật An toàn, vệ sinh lao động 2015. Những ngày nghỉ này không bị trừ vào phép năm. • Nếu bạn nghỉ do ốm đau thông thường, bạn sẽ được hưởng chế độ ốm đau do BHXH chi trả, không phải do công ty chi trả."}, {"u": "./chapter_2.html#chapter-2__8", "c": "Chương 2", "k": "2", "n": 31, "q": "Nếu tôi bị chấn thương do tai nạn lao động và không thể tiếp tục làm công việc hiện tại, liệu công ty có sắp xếp cho tôi làm việc ở vị trí khác phù hợp hơn không?", "a": "Theo Điều 38 Luật An toàn, vệ sinh lao động 2015: • Công ty có nghĩa vụ bố trí công việc phù hợp hơn với tình trạng sức khỏe của người lao động nếu bạn bị suy giảm khả năng lao động. • Nếu không thể bố trí, hai bên có thể thỏa thuận chấm dứt hợp đồng, nhưng phải thực hiện các thủ tục hỗ trợ/bồi thường theo đúng qui định của pháp luật."}, {"u": "./chapter_2.html#chapter-2__9", "c": "Chương 2", "k": "2", "n": 32, "q": "Nếu tôi bị chấn thương do tai nạn lao động và không thể tiếp tục làm công việc hiện tại, tôi có được bồi thường không? Thủ tục bồi thường như thế nào?", "a": "- Bạn được bồi thường theo Điều 38-39 Luật An toàn, vệ sinh lao động nếu tai nạn xảy ra trong quá trình làm việc do lỗi của người sử dụng lao động. - Thủ tục gồm: 1. Khai báo tai nạn và lập biên bản điều tra (do công ty phối hợp với công đoàn thực hiện). 2. Đi giám định mức suy giảm khả năng lao động (tại Hội đồng giám định y khoa). 3. Hồ sơ gồm: biên bản tai nạn, kết luận giám định, đơn đề nghị hưởng trợ cấp, sổ BHXH... 4. Nộp hồ sơ cho BHXH để được giải quyết trợ cấp hoặc bồi thường."}, {"u": "./chapter_2.html#chapter-2__10", "c": "Chương 2", "k": "2", "n": 33, "q": "Đồng nghiệp của tôi không may qua đời do tai nạn lao động tại công ty. Chủ công ty và BHXH có phải bồi thường cho anh ấy không?", "a": "Theo Luật ATVSLĐ và Luật BHXH: • Người sử dụng lao động phải bồi thường cho thân nhân người lao động nếu tai nạn do lỗi của công ty. • BHXH chi trả trợ cấp tử tuất nếu người lao động tham gia đủ điều kiện. • Ngoài ra, công ty phải hỗ trợ chi phí mai táng và các khoản khác theo thỏa thuận hoặc quy chế nội bộ."}, {"u": "./chapter_2.html#chapter-2__11", "c": "Chương 2", "k": "2", "n": 34, "q": "Thủ tục bồi thường sẽ được thực hiện như thế nào?", "a": "Các bước chính của thủ tục bồi thường: Bước 1 Bước 2 Điều tra tai nạn và lập biên bản xác nhận. Giám định sức khỏe (hoặc giấy chứng tử nếu tử vong). Bước 4 Bước 3 Nộp cho cơ quan BHXH hoặc công ty Chuẩn bị hồ sơ gồm: (tùy chế độ cần nhận). a. Biên bản tai nạn, quyết định giám định y khoa b. Đơn đề nghị trợ cấp c. Giấy tờ tùy thân d. Sổ BHXH (nếu có) Bước 5 Giải quyết bồi thường trong thời hạn tối đa 10-30 ngày theo quy định."}, {"u": "./chapter_2.html#chapter-2__12", "c": "Chương 2", "k": "2", "n": 35, "q": "Trong trường hợp phải điều trị tại bệnh viện, tôi sẽ được hưởng chế độ bảo hiểm như thế nào?", "a": "Nếu bạn có tham gia bảo hiểm y tế (BHYT): • Nếu không phải tai nạn lao động: Được chi trả một phần hoặc toàn bộ chi phí khám chữa bệnh theo mức hưởng BHYT. Mức hưởng bảo hiểm y tế tuỳ theo cơ sở y tế bạn nằm điều trị. • Nếu là tai nạn lao động có xác nhận: ngoài BHYT, bạn còn được hưởng trợ cấp từ BHXH (theo nội dung các câu hỏi và trả lời ở trên)."}, {"u": "./chapter_2.html#chapter-2__13", "c": "Chương 2", "k": "2", "n": 36, "q": "Tôi có được khám sức khỏe định kỳ nếu làm việc theo hợp đồng bán thời gian hoặc thời vụ không?", "a": "- Theo Điều 21 Luật ATVSLĐ 2015, người sử dụng lao động có trách nhiệm tổ chức khám sức khỏe định kỳ cho người lao động có hợp đồng lao động từ 3 tháng trở lên, kể cả hợp đồng bán thời gian hoặc thời vụ. - Nếu bạn ký hợp đồng dưới 3 tháng hoặc không ký hợp đồng thì không thuộc diện bắt buộc, trừ khi công việc có yếu tố nguy hiểm."}, {"u": "./chapter_2.html#chapter-2__14", "c": "Chương 2", "k": "2", "n": 37, "q": "Khám sức khỏe định kỳ cho người lao động (cả nam giới và nữ giới) sẽ bao gồm thăm khám và xét nghiệm nào?", "a": "Theo Luật An toàn, Vệ sinh Lao động 2015, người lao động được khám sức khỏe định kỳ ít nhất 01 lần/năm; riêng người lao động làm việc trong điều kiện độc hại, nguy hiểm được khám sức khỏe định kỳ 06 tháng/lần. Theo Thông tư 14/2013/TT-BYT, khám sức khỏe định kỳ thường bao gồm: • Khám lâm sàng toàn diện: • Các cận lâm sàng cơ bản: Nội khoa, ngoại khoa, mắt, tai - Công thức máu, nước tiểu, đo mũi - họng, răng - hàm - mặt, huyết áp, điện tim, chụp da liễu.. X-quang phổi. • Đối với người lao động nữ: • Nếu làm việc trong môi Có thể thêm siêu âm ổ bụng, trường độc hại: Sẽ có thêm các xét nghiệm phụ khoa nếu cần. xét nghiệm chuyên biệt như chức năng gan, thận, xét nghiệm chì/mangan/thủy ngân trong máu... • Đối với xét nghiệm HIV, bạn có thể yêu cầu khi khám sức khoẻ định kỳ, tuy nhiên bạn có thể phải trả phí cho xét nghiệm này. Bạn có thể đến các Trung tâm hỗ trợ xét nghiệm HIV tự nguyện theo các số điện thoại đường dây nóng về xét nghiệm HIV gần nơi bạn làm việc."}, {"u": "./chapter_2.html#chapter-2__15", "c": "Chương 2", "k": "2", "n": 38, "q": "Tôi làm công việc liên quan tới hóa chất và chất độc hại tại nhà máy. Tôi có được khám sức khỏe định kỳ thường xuyên hơn không? Ngoài ra, nếu mắc bệnh nghề nghiệp, tôi sẽ được hưởng những quyền lợi và hỗ trợ nào?", "a": "Bạn được khám sức khoẻ định kỳ thường xuyên hơn người lao động ở các công ty khác. - Theo quy định tại Điều 21 Luật An toàn, vệ sinh lao động 2015 và Thông tư 14/2013/TT-BYT: • Người lao động làm việc trong môi trường độc hại phải được khám sức khỏe ít nhất 2 lần/năm (nhiều hơn so với định kỳ 01 lần/năm cho người lao động bình thường). • Nếu mắc bệnh nghề nghiệp: bạn sẽ được hưởng các chế độ sau từ BHXH: • Trợ cấp bệnh nghề nghiệp (một lần hoặc hàng tháng). • Chi trả chi phí y tế, phục hồi chức năng. • Chuyển đổi công việc phù hợp sức khỏe nếu cần."}, {"u": "./chapter_2.html#chapter-2__16", "c": "Chương 2", "k": "2", "n": 39, "q": "Anh Thọ hỏi: Bạn anh là một người làm trong nhà máy sản xuất xi-măng 3 năm, bị bệnh bụi phổi. Như vậy có phải bệnh nghề nghiệp không?", "a": "- Bạn anh gần như chắc chắn là bị bệnh nghề nghiệp. - Theo Thông tư 02/2023/TT-BYT, bệnh bụi phổi (silic) là một trong các bệnh nghề nghiệp được bảo hiểm nếu người lao động thường xuyên tiếp xúc với bụi silic trong quá trình làm việc, điển hình trong ngành xi măng, khai thác đá..."}, {"u": "./chapter_2.html#chapter-2__17", "c": "Chương 2", "k": "2", "n": 40, "q": "Nếu đúng là bệnh nghề nghiệp, thì bạn anh được hưởng những quyền lợi gì?", "a": "Nếu đúng là bệnh nghề nghiệp, bạn của anh Thọ sẽ được: • Khám và điều trị miễn phí bệnh nghề nghiệp tại cơ sở y tế chỉ định. • Trợ cấp bệnh nghề nghiệp (theo mức suy giảm khả năng lao động). • Phục hồi chức năng, cấp dụng cụ hỗ trợ. • Hỗ trợ chuyển đổi nghề nếu không tiếp tục được công việc cũ. Tất cả các quyền lợi này đều được chi trả từ Quỹ BHXH tai nạn lao động và bệnh nghề nghiệp."}, {"u": "./chapter_2.html#chapter-2__18", "c": "Chương 2", "k": "2", "n": 41, "q": "Tôi là Mai, 23 tuổi, người lao động đến từ một tỉnh phía Bắc chưa kết hôn, làm trong công ty linh kiện điện tử của nước ngoài được hai năm. Quản lý trực tiếp tôi là người Việt Nam. Người quản lý này thường la mắng và đối xử bất công với tôi tại nơi làm việc do tôi không đồng ý một số yêu cầu khiếm nhã của ông ấy. Tôi nên làm gì trong trường hợp này?", "a": "• Hành vi khiếm nhã là hành vi thiếu tế nhị, thiếu chuẩn mực, thậm chí là thô lỗ, thể hiện sự thiếu tôn trọng đối với người khác. Ví dụ: Nói xấu, xúc phạm danh dự, bắt làm việc ngoài giờ mà không được trả công, giễu cợt…) • Trong trường hợp này, yêu cầu người quản lý chấm dứt ngay hành vi trên, nếu người quản lý vẫn tiếp tục hành vi khiếm nhã, chị có thể thu thập các chứng cứ gửi lên công đoàn, hoặc cấp cao hơn để xử lý vấn đề này."}, {"u": "./chapter_2.html#chapter-2__19", "c": "Chương 2", "k": "2", "n": 42, "q": "Tôi thường xuyên bị một đồng nghiệp nam cư xử rất khó chịu và hay nhận xét các bộ phận nhạy cảm của tôi và đồng nghiệp nữ tại nơi làm việc. Đây có phải là hành vi quấy rối tình dục không?", "a": "Khái niệm cơ bản về quấy rối tình dục Đây là một dạng của hành vi quấy rối tình dục tại nơi làm việc. Để hiểu rõ hơn về các hành vi quấy rối tình dục chị có thể tham khảo ở Hộp 2.3 Quấy rối tình dục là mọi hành vi mang tính chất tình dục xảy ra do không mong muốn gây xúc phạm nhân phẩm hoặc làm tổn thương tâm lý, đồng thời khi hành vi đó cản trở công việc bị áp đặt như một điều kiện làm việc hoặc tạo ra môi trường làm việc đáng sợ, thù địch hoặc xúc phạm. Các hình thức quấy rối tình dục bao gồm: • Quấy rối tình dục mang tính thể chất: Bao gồm tất cả các động chạm không mong muốn xảy ra như cố ý sờ mó, động chạm, vuốt ve, cấu véo, ôm hoặc hôn nhằm tấn công tình dục hoặc cưỡng hiếp. • Quấy rối tình dục bằng lời nói: Bao gồm những bình luận tục tĩu, trêu chọc, khiếm nhã, hoặc thậm chí gọi một người với biệt danh phản cảm, khiến đối phương cảm thấy bị phân biệt đối xử hoặc bị làm nhục. • Quấy rối tình dục phi ngôn ngữ: Bao gồm những hành vi không được chào đón như cử chỉ, ngôn ngữ cơ thể mang tính khêu gợi, hành vi không đứng đắn, ánh mắt dâm đãng, nháy mắt lặp đi lặp lại và cử chỉ bằng ngón tay mang hàm ý khiếm nhã đồng thời còn bao gồm việc hiển thị không mong muốn các tài liệu khiêu dâm, hình ảnh và đồ vật khiêu dâm, trình bảo vệ màn hình hoặc áp phích cũng như các email, ghi chú hoặc tin nhắn có nội dung khiêu dâm. • Quấy rối tình dục qua mạng: Từ các email hoặc tin nhắn SMS có nội dung xúc phạm, khiêu dâm hoặc những lời tán tỉnh không phù hợp, trên các trang mạng xã hội. (Theo Liên hợp quốc)"}, {"u": "./chapter_2.html#chapter-2__20", "c": "Chương 2", "k": "2", "n": 43, "q": "Tôi và các bạn nữ bị anh ta cư xử như vậy, chúng tôi nên làm gì?", "a": "Bạn nên yêu cầu đồng nghiệp nam có cư xử đúng mực, tôn trọng và văn minh. Trong trường hợp nam đồng nghiệp vẫn tiếp tục có những hành vi như trên, bạn nên báo cáo với cấp trên để được bảo vệ và tránh không bị quấy rối tại nơi làm việc."}, {"u": "./chapter_2.html#chapter-2__21", "c": "Chương 2", "k": "2", "n": 44, "q": "Bạn tôi làm trong một nhà hàng của một công ty khá nổi tiếng. Cô ấy thường bị khách hàng quấy rối tình dục (có hành vi đụng chạm không phù hợp, rủ đi chơi, thậm chí gạ gẫm qua đêm) khiến cô ấy cảm thấy bị xúc phạm. Tôi nên khuyên bạn tôi làm gì?", "a": "• Nói với bạn của mình yêu cầu khách hàng phải chấm dứt ngay hành vi quấy rối tình dục với cô ấy. • Trong trường hợp khách hàng vẫn tiếp tục hành vi quấy rối, báo cáo ngay với quản lý công ty để được hỗ trợ và bảo vệ; đồng thời thu thập những bằng chứng liên quan để làm cơ sở xử lý và chấm dứt tình trạng quấy rối này."}, {"u": "./chapter_2.html#chapter-2__22", "c": "Chương 2", "k": "2", "n": 45, "q": "Bạn của chị Ngọc làm giúp việc cho một gia đình. Gần đây, ông chủ có hành vi cố tình chạm vào mông, kèm theo những lời nói đùa cợt, gạ gẫm đi chơi. Hành vi này của ông chủ có phải là bình thường không? Bạn của chị Ngọc rất lo lắng, chị ấy nên làm gì?", "a": "• Đây là hành vi quấy rối tình dục mang tính chất thể chất từ phía ông chủ đối với người lao động. • Bạn của chị cần thể hiện rõ thái độ, yêu cầu ông chủ chấm dứt ngay hành vi quấy rối. • Trong trường hợp ông chủ vẫn tiếp tục hành vi này, nên chủ động thu thập bằng chứng (ghi âm, tin nhắn, hình ảnh…) và gửi đến các cơ quan, tổ chức có thẩm quyền như Hội Liên hiệp Phụ nữ, Công đoàn hoặc cơ quan công an để được hỗ trợ, bảo vệ."}, {"u": "./chapter_2.html#chapter-2__23", "c": "Chương 2", "k": "2", "n": 46, "q": "Bạn gái của Mai cho biết cô ấy đã bị bạn trai ép quan hệ tình dục trong khi bạn ấy chưa sẵn sàng cho việc này, hiện bạn ấy rất lo lắng. Trong trường hợp này, có phải bạo lực tình dục không?", "a": "Quan hệ tình dục lành mạnh là sự tự nguyện, mong muốn thực hiện hành vi quan hệ tình dục của cả hai người. Nếu một trong hai người không muốn, bị ép/ bắt đối phương phải quan hệ tình dục thì được xem là bạo lực tình dục. Bảng 2.5 Bạo lực về tình dục • Dùng vũ lực cưỡng ép người khác quan hệ tình dục trái với ý muốn của họ, cho dù đã thực hiện được hành vi đó hay chưa. • Tìm cách hoặc thực hiện quan hệ tình dục với người không có nhận thức hoặc làm chủ hành vi, không hiểu được bản chất của hành động đó. • Hành động lạm dụng đụng chạm dâm ô, bao gồm sờ soạng trực tiếp hoặc qua quần áo vào các vùng nhạy cảm (bộ phận sinh dục, hậu môn, háng, ngực, bẹn, mông) của người khác khi chưa có sự đồng ý."}, {"u": "./chapter_2.html#chapter-2__24", "c": "Chương 2", "k": "2", "n": 47, "q": "Bạn của tôi cần phải làm gì trong trường hợp này?", "a": "• Trước hết, bạn ấy cần uống ngay viên thuốc tránh thai khẩn cấp và uống thuốc dự phòng về lây truyền qua đường tình dục (cần được bác sĩ tư vấn). • Hãy đến cơ sở y tế gần nhất có chuyên môn phù hợp và có uy tín để được thăm khám và có hướng xử lý kịp thời. Việc tiếp theo cần làm: • Yêu cầu người bạn trai mới quen chấm dứt ngay hành vi ép quan hệ tình dục khi bản thân không mong muốn. • Có thể lưu giữ những bằng chứng để giải quyết vấn đề này một cách thích đáng."}, {"u": "./chapter_3.html#chapter-3__1", "c": "Chương 3", "k": "3", "n": 48, "q": "Anh Đạt hỏi: Tôi chưa kết hôn nhưng có nhu cầu quan hệ tình dục. Khi quan hệ, tôi cần làm gì để đảm bảo an toàn?", "a": "• Tình dục an toàn là quan hệ tình dục không mang thai ngoài ý muốn và không bị các bệnh lây truyền qua đường tình dục, bao gồm cả HIV. • Biện pháp tốt nhất để đảm bảo tình dục an toàn cho thanh niên chưa kết hôn là sử dụng bao cao su (nam/nữ) thanh niên cần tìm hiểu kỹ về các biện pháp tránh thai và cách sử dụng bao cao su đúng cách. • Ngoài tình dục an toàn, nam/nữ thanh niên khi quan hệ tình dục cần có sự tự nguyện, tôn trọng lẫn nhau, không làm tổn thương tình thần và thể chất từ cả hai phía. Như vậy mới đảm bảo tình dục an toàn, lành mạnh và có văn hoá."}, {"u": "./chapter_3.html#chapter-3__2", "c": "Chương 3", "k": "3", "n": 49, "q": "Tại sao cần sử dụng bao cao su đúng cách? Sử dụng bao cao su đúng cách là như thế nào?", "a": "• Nếu bạn không sử dụng bao cao su (BCS) đúng cách, sẽ không đạt được độ an toàn tuyệt đối (vẫn có thể có thai ngoài ý muốn và lây bệnh qua đường tình dục). • Sử dụng BCS đúng cách là dùng BCS chất lượng tốt (không thủng, rách, còn hạn sử dụng, không bị cắt hay chọc thủng), dùng ngay khi bắt đầu giao hợp (dùng sai là không dùng BCS từ khi bắt đầu quan hệ tình dục, mà chỉ dùng sau khi đã giao hợp và đeo BCS khi sắp phóng tinh). LƯU Ý : Ngoài vỏ bao cao su luôn có hướng dẫn cách sử dụng BCS đúng cách. Bạn nên đọc kỹ và học cách sử dụng đúng trước khi dùng."}, {"u": "./chapter_3.html#chapter-3__3", "c": "Chương 3", "k": "3", "n": 50, "q": "Sau khi quan hệ tình dục với bạn gái, tôi thấy bị đau khi đi tiểu. Tôi gặp vấn đề gì?", "a": "- Bạn đã có thể bị viêm đường sinh dục hoặc bị bệnh lây truyền qua đường tình dục. - Nếu thấy có các dấu hiệu này bạn nên đi khám ngay. - Các dấu hiệu của bệnh lây truyền qua đường tình dục bạn tham khảo trong bảng 3.1"}, {"u": "./chapter_3.html#chapter-3__4", "c": "Chương 3", "k": "3", "n": 51, "q": "Tôi là Mai, chưa kết hôn. Tôi và bạn trai có quan hệ tình dục nhưng chưa muốn có thai. Ngoài việc dùng bao cao su, nam và nữ thanh niên có thể áp dụng biện pháp tránh thai nào khác?", "a": "• Có nhiều phương pháp tránh thai để các bạn cân nhắc sử dụng khi chưa kết hôn. Các biện pháp tránh thai hiện đại (ngoài Bao cao su) có thể là: thuốc viên tránh thai cho nữ, tiêm thuốc tránh thai, que cấy tránh thai, đặt vòng tránh thai, màng ngăn âm đạo. Bạn có thể dùng thuốc tránh thai hàng ngày, nhưng cần chọn loại phù hợp và sử dụng đúng cách. • Khi chưa kết hôn các bạn nữ không nên chọn các phương pháp dài hạn như đặt vòng, tiêm thuốc hay cấy que tránh thai. • Các phương pháp tránh thai vĩnh viễn như triệt sản tuyệt đối không nên áp dụng khi chưa kết hôn đối với cả nam và nữ. • Bạn có thể sử dụng các phương pháp tránh thai tự nhiên như theo dõi chu kỳ kinh nguyệt để xác định ngày an toàn (nếu kinh nguyệt đều), hoặc xuất tinh ngoài âm đạo. LƯU Ý : Khi chưa kết hôn mà có quan hệ tình dục, biện pháp tránh thai tốt nhất là sử dụng bao cao su, vừa có tác dụng tránh thai và vừa tránh lây truyền các bệnh qua đường tình dục."}, {"u": "./chapter_3.html#chapter-3__5", "c": "Chương 3", "k": "3", "n": 52, "q": "Nếu đi khám, tôi nên đến đâu?", "a": "• Nếu có một trong các biểu hiện như trên sau khi có quan hệ tình dục, bạn cần đến ngay các cơ sở y tế để khám và xác định chắc chắn bạn có bị một hay nhiều bệnh lây truyền qua đường tình dục (LTQĐTD). • Bạn cần chọn các cơ sở y tế có chuyên môn phù hợp và có uy tín. • Bạn có thể đến khám tại các cơ sở y tế: Bệnh viện da liễu các tuyến, Khoa Bệnh da liễu của các bệnh viện Đa khoa, các phòng khám tư nhân có chuyên môn phù hợp và có uy tín."}, {"u": "./chapter_3.html#chapter-3__6", "c": "Chương 3", "k": "3", "n": 53, "q": "Nếu tôi được chẩn đoán là mắc một trong các bệnh lây truyền qua đường tình dục, tôi có thể tự điều trị được không? Nếu không chữa trị các bệnh lây truyền qua đường tình dục cẩn thận, tôi có thể bị hậu quả gì?", "a": "• Bạn không nên tự điều trị, mà nên tuân theo chỉ định điều trị của bác sĩ. Tự điều trị có thể dẫn đến nhiều hậu quả không tốt. • Nếu không chữa trị, các bệnh lây truyền qua đường tình dục có thể bị biến chứng nặng dẫn đến nhiễm trùng máu, tâm thần (hậu quả của bệnh giang mai), và về lâu dài có thể dẫn đến vô sinh."}, {"u": "./chapter_3.html#chapter-3__7", "c": "Chương 3", "k": "3", "n": 54, "q": "Anh Đạt hỏi: Làm thế nào để tôi có thể bảo vệ bản thân khỏi các bệnh lây truyền qua đường tình dục?", "a": "Biện pháp bảo vệ bản thân khỏi các bệnh lây truyền qua đường tình dục: • Không quan hệ tình dục với người không quen biết hoặc mới quen mà chưa rõ về họ. • Nếu có quan hệ tình dục bạn cần luôn dùng bao cao su đúng cách. • Quan hệ chung thuỷ một bạn tình (chỉ với người yêu hoặc vợ/chồng mình)."}, {"u": "./chapter_3.html#chapter-3__8", "c": "Chương 3", "k": "3", "n": 55, "q": "Anh Đạt hỏi: Bạn tôi làm cùng công ty và mới đi xét nghiệm máu được thông báo là đã nhiễm HIV (anh ấy lo sợ không dám nói với ai). Liệu bạn tôi có cần phải thông báo với người quản lý hoặc người sử dụng lao động) không?", "a": "Anh ấy không bắt buộc phải thông báo tình trạng nhiễm HIV cho quản lý của công ty. Tuy nhiên, bạn của anh có thể cân nhắc một số vấn đề sau: • Sức khỏe và điều trị: Điều quan trọng nhất là bạn của anh cần tham gia điều trị kháng HIV bằng thuốc ARV càng sớm càng tốt, tập trung vào việc điều trị và quản lý sức khỏe của mình. Việc tuân thủ điều trị ARV đều đặn sẽ giúp duy trì sức khỏe tốt, kéo dài tuổi thọ và giảm đến 97% nguy cơ lây truyền HIV sang người khác qua quan hệ tình dục. • Hỗ trợ tâm lý: Việc đối mặt với chẩn đoán nhiễm HIV có thể rất khó khăn về mặt tâm lý. Bạn của anh nên tìm kiếm sự hỗ trợ từ các chuyên gia y tế, tổ chức cộng đồng về HIV/AIDS hoặc những người thân đáng tin cậy. • Nếu bạn của anh lo lắng về việc bị phân biệt đối xử hoặc có bất kỳ thắc mắc nào khác về quyền lợi của mình, anh ấy có thể tìm đến sự tư vấn từ các tổ chức cộng đồng tham gia hoạt động phòng, chống HIV/AIDS, tổ chức trợ giúp pháp lý hoặc các cơ quan đầu mối phòng, chống HIV/AIDS tại địa phương trực thuộc Trung tâm kiểm soát bệnh tật tỉnh, thành phố để được tư vấn và hỗ trợ."}, {"u": "./chapter_3.html#chapter-3__9", "c": "Chương 3", "k": "3", "n": 56, "q": "Tôi là Đạt. Tôi đã có người yêu ở quê và gần đây tôi có quan hệ tình dục với một cô gái (tôi có quen nhưng không biết nhiều về cô ấy). Tôi đang rất lo sợ bị mắc bệnh lây truyền qua đường tình dục do mối quan hệ này. Tôi có thể bị mắc bệnh gì khi tôi có quan hệ tình dục như vậy?", "a": "Bạn có nguy cơ bị mắc các bệnh lây truyền qua đường tình dục, các bệnh đó có thể là: Lậu, giang mai, giận mu, bệnh sùi mào gà, mụn rộp sinh dục… và nguy hiểm nhất là nhiễm HIV."}, {"u": "./chapter_3.html#chapter-3__10", "c": "Chương 3", "k": "3", "n": 57, "q": "Nếu không may bị mắc các bệnh đó, tôi có thể nhận biết qua các biểu hiện nào?", "a": "Bạn xem bảng 3.1, tuỳ theo bạn là nam hay nữ để đối chiếu các triệu chứng, nếu có một trong các triệu chứng giống với các triệu chứng mô tả ở bảng dưới đây, bạn cần đến các cơ sở y tế để khám và điều trị. Bảng 3.1 Các dấu hiệu thường thấy khi bị mắc các bệnh lây truyền qua đường tình dục Điều quan trọng là bạn cần nhận biết được các dấu hiệu của bệnh lây truyền qua đường tình dục. Các dấu hiệu thường thấy khi bị mắc các bệnh lây truyền qua đường tình dục đối với mỗi giới thường có các dấu hiệu điển hình sau: • Đối với nữ: • Đối với nam: • Ra khí hư (dịch tiết âm đạo) bất • Đi tiểu buốt hoặc đi nhiều lần hơn thường: có mùi hôi, tanh, màu đỏ máu, bình thường. màu xanh hoặc mủ. • Chảy dịch bất thường (mủ) từ • Đi tiểu bị đau buốt, rát hoặc đi tiểu dương vật. nhiều lần. • Sưng tấy, xuất hiện các nốt lạ hoặc vết • Vùng sinh dục đỏ, sưng, xuất hiện các loét bộ phận sinh dục. nốt lạ, gây đau. • Có thể có triệu chứng sốt. • Đau bụng dưới hoặc đau bụng khi • Riêng đối với lây truyền HIV, có thể đang quan hệ tình dục. không có bất kỳ dấu hiệu trên, mà chỉ • Đôi khi có sốt, ớn lạnh. biết được thông qua xét nghiệm máu."}, {"u": "./chapter_3.html#chapter-3__11", "c": "Chương 3", "k": "3", "n": 58, "q": "Tôi có nên nói việc mình có những biểu hiện bất thường với cô gái mà tôi đã quan hệ không?", "a": "Bạn nên nói với cô gái đó và khuyên cô ấy đi khám (cô ấy có thể chưa biết chính bản thân đã bị mắc các bệnh lây truyền qua đường tình dục)."}, {"u": "./chapter_3.html#chapter-3__12", "c": "Chương 3", "k": "3", "n": 59, "q": "Kinh nguyệt của tôi không được đều. Tôi nên làm gì?", "a": "- Kinh nguyệt của bạn không đều có thể do nhiều nguyên nhân, như chế độ làm vệc nghỉ ngơi không điều độ, do rối loạn nội tiết hoặc ảnh hưởng của thuốc điều trị bệnh khác. Ngoài ra, cũng có nhiều phụ nữ kinh nguyệt không đều nhưng không xác định được rõ nguyên nhân. - Bạn nên đi khám bác sĩ để tìm hiểu về tình trạng của mình. - Kinh nguyệt không đều không quá nguy hiểm, có thể sẽ đều sau một thời gian nhất định. - Kinh nguyệt đang rất đều mà thay đổi sang không đều và thất thường thì bạn nên đi khám. Bạn không nên tự điều trị mà không có hướng dẫn của người có chuyên môn (bác sĩ, dược sĩ,…)."}, {"u": "./chapter_3.html#chapter-3__13", "c": "Chương 3", "k": "3", "n": 60, "q": "Tôi thấy nhiều đồng nghiệp nữ và bạn tôi nói là mỗi lần sinh hoạt tình dục xong lại uống thuốc tránh thai khẩn cấp. Liệu thuốc tránh thai khẩn cấp có nguy hiểm và gây hậu quả gì không?", "a": "Việc sử dụng thuốc tránh thai khẩn cấp thường xuyên là không tốt và có thể gây hậu quả lâu dài đến sức khỏe sinh sản. Lạm dụng thuốc có thể làm rối loạn nội tiết và nguy cơ dẫn đến hậu quả nguy hiểm đó là vô sinh ở nữ giới. LƯU Ý : • Trong hướng dẫn sử dụng của thuốc tránh thai khẩn cấp luôn ghi rõ giới hạn số lượng thuốc được dùng trong một khoảng thời gian nhất định. Ví dụ: Chỉ được dùng 1 lần (1 hoặc 2 viên) trong vòng 1 tháng). • Bên cạnh đó, sử dụng thuốc tránh thai khẩn cấp không thể phòng các bệnh lây truyền qua đường tình dục và nhiễm HIV."}, {"u": "./chapter_3.html#chapter-3__14", "c": "Chương 3", "k": "3", "n": 61, "q": "Tôi nên dùng thuốc tránh thai khẩn cấp trong trường hợp nào?", "a": "• Thuốc tránh thai khẩn cấp chỉ được sử dụng trong trường hợp khẩn cấp: Rách bao cao su, quan hệ tình dục không mong muốn, bị xâm hại,… • Nếu bạn quan hệ tình dục với bạn trai mà chưa chuẩn bị bao cao su, bạn có thể dùng thuốc tránh thai khẩn cấp. Tuy nhiên, phải sử dụng đúng theo hướng dẫn, không được dùng nhiều hơn số lần được phép dùng theo hướng dẫn sử dụng."}, {"u": "./chapter_3.html#chapter-3__15", "c": "Chương 3", "k": "3", "n": 62, "q": "Tôi 22 tuổi, đã có bạn trai và thỉnh thoảng chúng tôi có quan hệ tình dục. Gần đây tôi thấy hay buồn nôn và chóng mặt nên lo lắng có thể đã mang thai nhưng hiện tại tôi chưa muốn lập gia đình. Nếu tôi có thai và không muốn sinh con thì tôi nên làm thế nào?", "a": "• Bạn nên mua que thử thai ở các hiệu thuốc và thử thai theo hướng dẫn. • Que thử lên 1 vạch đỏ là bạn không có thai, que thử lên 2 vạch rõ là bạn đã có thai. • Nếu bạn không muốn sinh con, bạn nên xem xét nguyên nhân không muốn sinh con và cân nhắc kỹ lưỡng. • Việc không muốn sinh con có thể do chính bản thân bạn và gia đình bạn không muốn, hoặc do bạn trai và gia đình bạn trai không muốn sinh ra đứa trẻ này. • Bước đầu tiên bạn nên bàn bạc với bạn trai để ra quyết định cuối cùng là nên giữ thai và sinh con hay phá thai. Nếu có thể, nên giữ thai để sinh con. • Bạn cần cho gia đình (đặc biệt là mẹ) biết về việc mình có thai để nhận được sự hỗ trợ và lời khuyên phù hợp. • Để quyết định phá thai, bạn cần tìm hiểu kỹ lưỡng thông tin liên quan, vì phá thai có những hậu quả không tốt trước mắt và lâu dài. không có thai có thai"}, {"u": "./chapter_3.html#chapter-3__16", "c": "Chương 3", "k": "3", "n": 63, "q": "Nếu tôi có thai ngoài ý muốn và muốn chấm dứt thai kỳ thì tôi phải làm thế nào?", "a": "- Nếu bạn muốn quyết định chấm dứt thai kỳ, cần chọn phương pháp phá thai an toàn để tránh hậu quả không mong muốn. Bạn nên đến cơ sở y tế được cấp phép và được bác sĩ có trình độ chuyên môn thực hiện. - Bạn cần xác định tuổi thai để xem có thể chấm dứt thai kỳ hay không. Theo qui định, việc phá thai khi tuổi thai dưới 22 tuần (tính từ ngày đầu của kỳ kinh cuối cùng). • Nên chấm dứt thai kỳ sớm (7-12 tuần tuổi) tại cơ sở y tế có uy tín, chất lượng tốt và thực hiện theo đúng hướng dẫn của bác sĩ. • Khi thai to (trên 12 tuần và dưới 22 tuần), bạn cần đến cơ sở y tế tuyến tỉnh trở lên để được xử lý an toàn. - Chăm sóc tốt sau phá thai: nghỉ ngơi, uống kháng sinh và một số loại thuốc khác theo đơn của bác sĩ, ăn uống đủ chất dinh dưỡng, kiêng quan hệ tình dục trong một tháng sau khi phá thai. Bạn cũng cần tuân thủ lịch khám lại theo chỉ định của bác sĩ. - Tuyệt đối không phá thai tại các cơ sở y tế không đủ uy tín, không đảm bảo chất lượng và không có đầy đủ phương tiện cấp cứu trong trường hợp có biến chứng nặng xảy ra. Bạn sẽ không được phá thai an toàn (nguy hiểm đến tính mạng) khi: • Đến các cơ sở phá thai không được phép thực hiện phá thai/không có giấy phép hành nghề (phòng khám tư nhân). • Đến các thầy lang vườn dùng các loại thuốc nam và thuốc bắc không được phép dùng. • Mua thuốc tự phá thai tại nhà, ăn/uống các đồ để nhằm sảy thai. • Tác động vật lý mạnh vào bụng, chạy nhảy, tự gây ngã… để sảy thai. • Thai quá to (trên 22 tuần tuổi thai)."}, {"u": "./chapter_3.html#chapter-3__17", "c": "Chương 3", "k": "3", "n": 64, "q": "Phá thai có nguy hiểm không?", "a": "• Phá thai không nguy hiểm nếu được thực hiện an toàn, đó là: • Phá thai tại cơ sở y tế uy tín, được phép phá thai, • Không bị xảy ra các biến chứng trong và ngay sau phá thai (thủng tử cung, chảy máu, nhiễm trùng) và không để lại hậu quả lâu dài (vô sinh do tắc vòi trứng…) • Phá thai không an toàn rất nguy hiểm, gây ra các biến chứng và để lại các hậu quả lâu dài, thậm chí ảnh hưởng đến tính mạng."}, {"u": "./chapter_3.html#chapter-3__18", "c": "Chương 3", "k": "3", "n": 65, "q": "Có người nói nếu phá thai sau này tôi có thể bị vô sinh? Điều này có đúng không?", "a": "Điều này có thể đúng nếu quá trình phá thai không an toàn gây nhiễm trùng tử cung, vòi trứng và phần phụ, dẫn đến hậu quả lâu dài là vô sinh thứ phát (là vô sinh sau khi đã từng có thai)."}, {"u": "./chapter_3.html#chapter-3__19", "c": "Chương 3", "k": "3", "n": 66, "q": "Tôi là Mai, 23 tuổi, sắp kết hôn. Nhiều bạn khuyên tôi nên đi xét nghiệm viêm gan B và HIV trước hôn nhân. Việc này có thực sự cần thiết không? Tại sao bạn lại khuyên tôi như vậy?", "a": "• Việc này rất tốt nếu bạn làm được. Bạn nên đăng ký khám sức khỏe tiền hôn nhân, trong đó đã có 2 xét nghiệm này (hoặc bạn có thể yêu cầu tuỳ vào gói khám). • Lời khuyên này rất hữu ích, vì nếu bạn biết tình trạng nhiễm HIV và viêm gan B của bản thân bạn, bạn có thể chủ động phòng ngừa lây truyền hai bệnh này cho con."}, {"u": "./chapter_3.html#chapter-3__20", "c": "Chương 3", "k": "3", "n": 67, "q": "Tôi nên đi xét nghiệm ở đâu?", "a": "• Bạn có thể xét nghiệm ở các bệnh viện/cơ sở y tế có khoa/phòng xét nhiệm từ tuyến tỉnh trở lên. • Bạn cũng có thể đến các phòng khám đa khoa, sản khoa hoặc khoa truyền nhiễm yêu cầu xét nhiệm máu để xác định nhiễm HIV và viêm gan B. Việc này khá đơn giản và bạn không cần cảm thấy e ngại. • Bạn cũng có thể đến một số trung tâm được khuyến cáo của chuyên viên tư vấn và xét nghiệm cho người nghi ngờ hoặc nhiễm HIV."}, {"u": "./chapter_3.html#chapter-3__21", "c": "Chương 3", "k": "3", "n": 68, "q": "Tôi đang mang thai và cảm thấy khoẻ mạnh, tôi có cần đi khám thai không?", "a": "• Bạn nên đi khám thai ngay sau khi biết mình đã mang thai, hoặc muộn nhất trong 3 tháng đầu. • Bạn nên làm việc điều độ, nghỉ ngơi và bổ sung các thuốc bổ theo hướng dẫn của nhân viên y tế khi đến khám thai."}, {"u": "./chapter_3.html#chapter-3__22", "c": "Chương 3", "k": "3", "n": 69, "q": "Tôi nên đi khám thai ở đâu?", "a": "• Bạn có thể đi khám thai ở các cơ sở y tế từ tuyến cơ sở (trạm y tế) cho đến tuyến cao nhất. Bạn cũng có thể khám tại các phòng khám tư nhân có uy tín. • Bạn nên hỏi kinh nghiệm các bạn bè, đồng nghiệp, người thân đã từng có thai gần đây."}, {"u": "./chapter_3.html#chapter-3__23", "c": "Chương 3", "k": "3", "n": 70, "q": "Tôi nên đi khám bao nhiêu lần trong kỳ mang thai? Và nên khám vào thời gian nào của thai kỳ?", "a": "• Theo khuyến cáo, bạn nên đi khám thai ít nhất 4 lần trong suốt thai kỳ. • Có 4 mốc khám thai quan trọng bạn cần ghi nhớ để theo dõi sức khỏe thai kỳ và phát hiện sớm các vấn đề tiềm ẩn: (1) Khám thai lần đầu khi phát hiện mang thai, (2) tuần 11-13, (3) tuần 20-24, và (4) tuần 30-32. • Có một số khuyến cáo cho rằng thai phụ nên khám thai nhiều lần hơn, 7-10 lần trong thai kỳ. Tuy nhiên khi bạn đến khám thai, các bác sĩ sẽ hẹn khám cho lần tiếp theo tuỳ theo tình trạng sức khoẻ của bạn và thai nhi. Bảng 3.2 Các mốc khám thai chi tiết: 1. Khám thai lần đầu: • Ngay sau khi thử que 2 vạch hoặc chậm kinh, bạn nên đi khám để xác nhận có thai, xác định vị trí thai và kiểm tra sức khỏe tổng quát. 2. Tuần 11-13: • Đây là giai đoạn quan trọng để thực hiện siêu âm đo độ mờ da gáy, tầm soát các dị tật bẩm sinh, cũng như các xét nghiệm sàng lọc trước sinh. 3. Tuần 20-24: • Siêu âm hình thái học ở giai đoạn này giúp bác sĩ đánh giá chi tiết sự phát triển của các cơ quan trong cơ thể thai nhi, bao gồm tim, phổi, não, và các chi. 4. Tuần 30-32: • Giúp theo dõi sự phát triển của thai nhi, đánh giá tình trạng sức khỏe của mẹ và bé, chuẩn bị cho quá trình sinh nở. Ngoài ra, bác sĩ có thể phát hiện các dị tật xuất hiện muộn. Tuỳ theo tình trạng thai nhi và tình hình sức khoẻ của mẹ, bác sĩ sẽ hẹn khám cho lần tiếp theo và tư vấn các bước chuẩn bị trước khi sinh."}, {"u": "./chapter_3.html#chapter-3__24", "c": "Chương 3", "k": "3", "n": 71, "q": "Tôi có phải tiêm hay uống thuốc gì trong thời kỳ mang thai không?", "a": "• Bạn sẽ phải tiêm phòng uốn ván nếu trước đó bạn chưa tiêm. Nếu không có gì bất thường, bạn không phải tiêm thuốc điều trị. • Bạn cần uống các thuốc bổ sung trong thời kỳ mang thai (theo chỉ định của bác sĩ). Nên hỏi bác sĩ nếu bạn muốn sử dụng bất kỳ loại thuốc nào."}, {"u": "./chapter_3.html#chapter-3__25", "c": "Chương 3", "k": "3", "n": 72, "q": "Người lao động nên làm gì khi cảm thấy căng thẳng trong công việc?", "a": "• Khi cảm thấy căng thẳng trong công việc, người lao động nên giải lao vài phút để thư giãn, hít thở sâu hoặc vận động nhẹ. • Có thể chia nhỏ công việc để giảm áp lực, sắp xếp các nhiệm vụ theo thứ tự ưu tiên rõ ràng. • Trò chuyện với đồng nghiệp, quản lý hoặc chuyên gia tâm lý cũng giúp giải tỏa cảm xúc. • Ngoài giờ làm, cần duy trì thói quen sinh hoạt lành mạnh như ngủ đủ giấc, ăn uống điều độ và tập thể dục đều đặn giúp cân bằng tâm trạng."}, {"u": "./chapter_3.html#chapter-3__26", "c": "Chương 3", "k": "3", "n": 73, "q": "Tôi rất nhớ gia đình và bạn bè trong quãng thời gian phải sống xa quê. Tôi có thể làm gì để bớt nhớ nhà?", "a": "Cảm giác nhớ nhà là bình thường khi xa gia đình, đặc biệt với người đi làm xa nhà. Bạn có thể: • Gọi điện và video call với người thân thường xuyên. Ví dụ: Thiết lập lịch gọi định kỳ vào cuối tuần để trò chuyện cùng gia đình. • Tham gia hoạt động cộng đồng tại nơi ở mới như các câu lạc bộ hoặc hội nhóm văn hóa để kết bạn và tạo mối liên hệ mới. • Lưu giữ các vật kỷ niệm như ảnh hoặc đồ dùng yêu thích từ quê nhà giúp gợi nhớ ký ức tích cực."}, {"u": "./chapter_3.html#chapter-3__27", "c": "Chương 3", "k": "3", "n": 74, "q": "Tôi đang mang thai con đầu lòng và nghe nhiều về trầm cảm đối với phụ nữ trong thời kỳ mang thai và sau sinh. Tôi nên làm gì?", "a": "Trầm cảm trong và sau sinh là vấn đề thường gặp và có thể gây hậu quả không tốt có hại đến cả mẹ và con. Để tránh điều này xảy ra, bạn có thể: • Tâm sự với người thân về cảm xúc của mình. • Tham gia các hoạt động vui vẻ nhẹ nhàng, nghe nhạc… • Tham gia lớp học tiền sản để được hướng dẫn và chia sẻ cùng các bà mẹ khác. • Gặp bác sĩ tâm lý nếu cảm thấy lo âu kéo dài. Ví dụ: Nếu bạn khó ngủ hoặc hay khóc vô cớ, hãy sớm tìm sự hỗ trợ chuyên môn."}, {"u": "./chapter_3.html#chapter-3__28", "c": "Chương 3", "k": "3", "n": 75, "q": "Tôi rất phân vân, có phải người có vấn đề về tâm thần là người điên không?", "a": "• Điều này không đúng, người có vấn đề về sức khỏe tâm thần không phải là “người điên”. Đây là một hiểu lầm phổ biến và mang tính kỳ thị. • Sức khỏe tâm thần bao gồm nhiều trạng thái như lo âu, trầm cảm, stress… mà bất kỳ ai cũng có thể gặp phải và hoàn toàn có thể điều trị được. Chỉ một số rất ít trường hợp rối loạn nặng mới ảnh hưởng đến nhận thức và hành vi."}, {"u": "./chapter_3.html#chapter-3__29", "c": "Chương 3", "k": "3", "n": 76, "q": "Tôi vừa chuyển việc sang công ty mới. Gần đây, tôi cảm thấy buồn, dễ cáu giận và khó kiểm soát cảm xúc. Tôi nên làm gì để cải thiện tâm trạng và cảm thấy tốt hơn?", "a": "Bạn nên: • Tập luyện thể • Nói chuyện • Nếu cảm dục thường với đồng giác này kéo xuyên để giảm nghiệp hoặc dài, hãy gặp căng thẳng. Ví bạn bè để giảm chuyên gia dụ: Chạy bộ mỗi bớt lo lắng. tâm lý để được ngày hoặc tập hỗ trợ. yoga có thể cải thiện tâm trạng."}, {"u": "./chapter_3.html#chapter-3__30", "c": "Chương 3", "k": "3", "n": 77, "q": "Tôi là lao động nữ tại công ty dệt may. Gần đây, tôi cảm thấy mất hứng thú với các hoạt động mình từng yêu thích và đôi khi nghĩ đến tự tử. Tôi nên làm gì?", "a": "Đây là dấu hiệu nghiêm trọng, bạn có thể thử các cách sau đây: • Tìm người tin cậy để chia sẻ ngay hoặc liên hệ với đường dây nóng hỗ trợ tâm lý. • Tham gia các hoạt động thư giãn như thể thao hoặc nghệ thuật để tìm niềm vui mới. • Nếu suy nghĩ tự tử trở nên thường xuyên, hãy gặp bác sĩ tâm thần hoặc nhà tâm lý học ngay lập tức để được hỗ trợ khẩn cấp."}, {"u": "./chapter_3.html#chapter-3__31", "c": "Chương 3", "k": "3", "n": 78, "q": "Người lao động nên làm gì để bảo vệ giấc ngủ khi phải làm việc ca đêm?", "a": "• Khi làm việc ca đêm, người lao động nên duy trì lịch ngủ cố định sau mỗi ca làm, tạo môi trường ngủ yên tĩnh, tối và mát để dễ ngủ hơn. • Tránh sử dụng thiết bị điện tử trước khi ngủ và hạn chế caﬀeine ít nhất 4–6 tiếng trước giờ ngủ. • Có thể dùng kính chống ánh sáng xanh hoặc kính râm khi ra ngoài buổi sáng để giảm ức chế melatonin. Nếu có thể, nên chợp mắt ngắn (20–30 phút) trong ca làm để giảm mệt mỏi. • Quan trọng nhất là duy trì lối sống lành mạnh, ăn uống đúng giờ và tập thể dục nhẹ thường xuyên."}, {"u": "./chapter_3.html#chapter-3__32", "c": "Chương 3", "k": "3", "n": 79, "q": "Thỉnh thoảng tôi bị chồng đánh khi anh ấy thua bạc và đòi tiền. Tôi cảm thấy suy nhược và mệt mỏi. Tôi nên làm gì?", "a": "Đây là tình huống bạo lực gia đình và bạn cần tìm nơi an toàn: • Liên hệ trung tâm bảo vệ phụ nữ hoặc đường dây nóng hỗ trợ bạo lực gia đình. • Bạn tìm đến người phụ trách Hội Phụ nữ của công ty hoặc địa phương nơi bạn làm việc để được tư vấn và hỗ trợ. • Nếu có thể, nhờ người thân giúp đỡ hoặc chuyển đến nơi tạm trú an toàn. • Ở Việt Nam, bạn có thể gọi số 111 để được tư vấn về bạo lực gia đình."}, {"u": "./chapter_3.html#chapter-3__33", "c": "Chương 3", "k": "3", "n": 80, "q": "Tôi là nữ lao động 35 tuổi, tôi sống cùng chồng và hai con. Công việc của tôi ở công ty là làm theo ca: 1 tuần làm đêm và 2 tuần làm ngày và sau tuần làm đêm tôi được nghỉ 2 ngày. Trong lúc làm việc ở công ty, tôi phải đứng toàn bộ thời gian để kiểm tra sản phẩm trong chuỗi công việc. Tôi nên làm gì để bản thân không bị căng thẳng và giảm mệt mỏi về cuộc sống hiện tại?", "a": "• Trong tuần làm đêm bạn cần sắp xếp thời gian ngủ ít nhất 6 tiếng sau ca làm việc. • Được nghỉ 2 ngày sau tuần làm đêm bạn nên sắp xếp để tham gia các hoạt động cùng các con và chồng. • Do công việc bạn phải đứng nhiều nên bạn tham khảo các bài tập luyện cho vùng lưng, cột sống, và nên ngồi nghỉ hoặc thể dục nhẹ nhàng sau mỗi 45 phút."}, {"u": "./chapter_3.html#chapter-3__34", "c": "Chương 3", "k": "3", "n": 81, "q": "Tôi là người đồng tính và cảm thấy mình dễ bị phân biệt đối xử. Điều này có ảnh hưởng tới sức khỏe tâm thần của tôi không? Tôi có thể gặp phải các vấn đề sức khoẻ gì?", "a": "• Có, phân biệt đối xử có thể gây căng thẳng tâm lý và làm tăng nguy cơ trầm cảm. • Người đồng tính và chuyển giới có nguy cơ cao mắc các rối loạn tâm thần (do nhiều nguyên nhân, trong đó có nguyên nhân chính là do bị kỳ thị từ mọi người). Hậu quả nghiêm trọng có thể dẫn đến ý nghĩ hoặc hành vi tự tử. • Về thể chất, người đồng tính có nguy cơ bị mắc các bệnh lây truyền qua đường tình dục và nhiễm HIV (đặc biệt là đồng tính nam)."}, {"u": "./chapter_3.html#chapter-3__35", "c": "Chương 3", "k": "3", "n": 82, "q": "Tôi nên làm gì và tìm đến đâu để được tư vấn?", "a": "Bạn có thể: • Tìm sự hỗ trợ từ các tổ chức bảo vệ quyền của những người đồng tính và chuyển giới (LGBT), đồng thời tham gia cộng đồng tích cực để được chia sẻ và giúp đỡ. • Đến trung tâm tư vấn tâm lý hoặc bệnh viện chuyên khoa tâm thần. • Tìm đường dây nóng hỗ trợ nếu bạn cần được tư vấn khẩn cấp."}, {"u": "./chapter_3.html#chapter-3__36", "c": "Chương 3", "k": "3", "n": 83, "q": "Chị Mai là công nhân trong một nhà máy điện tử tại khu công nghiệp (KCN) ở Hà Nội, nơi có mật độ công nhân cao và điều kiện sống khá khó khăn. Chị thuê nhà trọ ở chung với bạn trai. Môi trường sống của chị Mai trong khu vực này là sự kết hợp giữa môi trường công nghiệp và sống trong khu trọ không đảm bảo về không gian sống và điều kiện vệ sinh. Liệu tình trạng ô nhiễm tiếng ồn và không khí là những yếu tố có thể ảnh hưởng đến sức khỏe của chị Mai và bạn trai chị không? Chị Mai và bạn trai nên làm gì để cải thiện môi trường sống tốt hơn?", "a": "• Môi trường công nghiệp có thể gây ra các bệnh lý nghề nghiệp như bệnh hô hấp do tiếp xúc với bụi bẩn, hóa chất, hoặc ô nhiễm không khí. • Ngoài ra, sống trong nhà trọ có thể dẫn đến thiếu ánh sáng tự nhiên, không khí kém và dễ bị stress. Theo nghiên cứu của Tổ chức Y tế Thế giới (WHO), ô nhiễm không khí có thể gây ra các bệnh tim mạch và hô hấp (WHO, 2018). • Cải thiện chất lượng nhà trọ: Chị Mai có thể tìm kiếm các nhà trọ có môi trường sống tốt hơn, đảm bảo vệ sinh, thông thoáng và không bị ẩm thấp. Sử dụng các thiết bị lọc không khí và cây xanh trong phòng để cải thiện chất lượng không khí. • Người lao động trong các khu công nghiệp nên kiểm tra chất lượng không khí từ các nguồn online (đơn giản nhất là trong Dự báo thời tiết của Zalo có thông báo hàng ngày). Nếu mức độ ô nhiễm không khí cao, người lao động nên hạn chế các hoạt động ngoài trời hoặc đeo khẩu trang khi ra ngoài. • Chế độ ăn uống và tập luyện: Đảm bảo chế độ ăn uống lành mạnh, bổ sung đủ vitamin và khoáng chất, đồng thời duy trì thói quen tập thể dục để tăng cường sức đề kháng. • Bảo vệ sức khỏe tại nơi làm việc: Sử dụng đầy đủ các thiết bị bảo vệ cá nhân (như khẩu trang chống bụi, găng tay, kính bảo vệ) khi làm việc trong môi trường có thể có bụi và hóa chất."}, {"u": "./chapter_3.html#chapter-3__37", "c": "Chương 3", "k": "3", "n": 84, "q": "Tôi mới chuyển đến thành phố mới sinh sống. Làm thế nào để tôi có thể tìm được nhà trọ phù hợp?", "a": "Bạn có thể tìm nhà trọ phù hợp bằng những cách như: - Tìm trên Internet hoặc ứng dụng tìm nhà trọ. - Nhờ sự giới thiệu từ bạn bè, đồng nghiệp hoặc người quen. - Tham khảo các trang web hoặc nhóm cộng đồng trên mạng xã hội chuyên về cho thuê phòng trọ. - Bạn nên tham khảo cuốn sách về Nhà ở an toàn của Tổ chức Di cư quốc tế sẽ có nội dung cụ thể hơn."}, {"u": "./chapter_3.html#chapter-3__38", "c": "Chương 3", "k": "3", "n": 85, "q": "Chị Ngọc (29 tuổi) và gia đình sống tại một khu công nghiệp ở Bắc Ninh, nơi có môi trường công nghiệp và ô nhiễm tiếng ồn. Chị Ngọc thường xuyên mất ngủ. Liệu sức khoẻ của chị Ngọc và gia đình có bị ảnh hưởng bởi tiếng ồn từ khu công nghiệp không?", "a": "• Môi trường công nghiệp có thể tác động tiêu cực đến sức khỏe trẻ em, bao gồm nguy cơ mắc các bệnh hô hấp và các vấn đề về tăng trưởng. Việc sống gần khu công nghiệp có thể làm tăng nguy cơ trẻ em bị nhiễm độc từ bụi bẩn, hóa chất và ô nhiễm tiếng ồn). • Cải thiện không gian sống: Chị Ngọc nên chọn nơi ở có không khí trong lành, ít ô nhiễm hơn và gần các không gian xanh như công viên hoặc cây cối. Nếu có thể, nên chuyển đến nơi có chất lượng không khí tốt hơn hoặc tạo không gian xanh trong nhà. • Duy trì sức khỏe gia đình: Tăng cường việc chăm sóc sức khỏe cho trẻ em, đặc biệt là phòng ngừa các bệnh về hô hấp, cung cấp đầy đủ dinh dưỡng và cho con chơi đùa ở nơi thoáng đãng. • Giảm tiếp xúc với ô nhiễm: Chị có thể đưa mẹ về quê sinh sống để hạn chế tác động của môi trường công nghiệp đến sức khỏe của bà và các cháu."}, {"u": "./chapter_3.html#chapter-3__39", "c": "Chương 3", "k": "3", "n": 86, "q": "Anh Đạt (25 tuổi) sống trong một khu trọ tại thành phố Đồng Nai cùng với các bạn đồng nghiệp. Môi trường sống của anh có thể gặp phải các vấn đề như thiếu không gian sống riêng tư, chất lượng nhà trọ không đảm bảo về vệ sinh, và điều kiện sống bị ảnh hưởng bởi sự đông đúc, tắc nghẽn của khu vực công nghiệp. Anh Đạt nên làm gì?", "a": "• Sống trong khu trọ có thể gây ảnh hưởng đến sức khỏe tâm lý và thể chất của anh Đạt, đặc biệt là trong các trường hợp có điều kiện sống không thuận lợi như thiếu vệ sinh, không khí kém, và không gian sống chật hẹp. Các nghiên cứu cho thấy môi trường sống kém chất lượng có thể gia tăng nguy cơ mắc các bệnh nhiễm trùng đường hô hấp, bệnh về da và các vấn đề về tâm lý như căng thẳng và lo âu. • Cải thiện không gian sống: Anh Đạt có thể tìm kiếm nhà trọ có không gian rộng rãi hơn và có các tiện nghi cơ bản như khu vệ sinh sạch sẽ, ánh sáng tự nhiên và không khí trong lành. • Đảm bảo vệ sinh cá nhân và vệ sinh chung: Dọn dẹp phòng trọ thường xuyên, sử dụng các thiết bị lọc không khí, giữ cho môi trường xung quanh sạch sẽ để giảm nguy cơ mắc các bệnh về da và hô hấp. • Thực hiện các biện pháp giảm căng thẳng: Anh Đạt có thể tham gia các hoạt động thể thao hoặc giải trí sau giờ làm việc để giảm căng thẳng, đồng thời duy trì một chế độ ăn uống lành mạnh, đủ chất dinh dưỡng."}, {"u": "./chapter_3.html#chapter-3__40", "c": "Chương 3", "k": "3", "n": 87, "q": "Nước sinh hoạt ở nhà trọ của tôi có vẻ không được tốt, nước có mùi và cặn bẩn. Điều này có ảnh hưởng đến sức khỏe của gia đình tôi tôi không? Tôi nên làm gì?", "a": "• Nước sinh hoạt không sạch sẽ, có mùi hoặc cặn bẩn có thể gây ra các bệnh về đường tiêu hóa như tiêu chảy, viêm ruột, và ảnh hưởng tới sức khỏe tổng quát. • Bạn nên: • Sử dụng máy lọc nước hoặc nước uống đóng chai để đảm bảo nguồn nước sạch cho ăn uống. • Thông báo tình trạng nước bẩn với chủ nhà trọ để họ kiểm tra và khắc phục. • Nếu không cải thiện, bạn nên cân nhắc chuyển sang nơi ở khác có nguồn nước đảm bảo hơn."}, {"u": "./chapter_3.html#chapter-3__41", "c": "Chương 3", "k": "3", "n": 88, "q": "Gần đây có một quán karaoke mới mở ngay cạnh nơi tôi ở. Tôi không thể ngủ được vì những tiếng ồn quá lớn từ quán karaoke. Điều này có hại cho sức khỏe của tôi không? Tôi nên làm gì?", "a": "- Tiếng ồn quá mức, đặc biệt vào ban đêm, có thể gây ảnh hưởng nghiêm trọng đến giấc ngủ và sức khỏe tinh thần, làm gia tăng stress và giảm chất lượng cuộc sống. - Bạn có thể: • Trao đổi với chủ nhà để họ làm việc với quán karaoke nhằm giảm tiếng ồn hoặc đề nghị ít nhất không làm ồn sau 22h. • Nếu không có cải thiện, bạn có thể phản ánh lên chính quyền địa phương hoặc cơ quan chức năng để kiểm tra và xử lý tiếng ồn. • Trong khi chờ giải quyết, sử dụng nút tai chống ồn hoặc các phương pháp giảm tiếng ồn khác để có thể ngủ tốt hơn."}, {"u": "./chapter_3.html#chapter-3__42", "c": "Chương 3", "k": "3", "n": 89, "q": "Khu trọ tôi ở rất chật chội, gần đây có nhiều người hàng xóm bị cúm A. Tôi nên làm gì để bảo vệ sức khỏe?", "a": "Khi có dịch bệnh như cúm A, bạn cần thực hiện các biện pháp phòng tránh sau: • Giữ vệ sinh cá nhân, rửa tay thường xuyên bằng xà phòng. • Đeo khẩu trang khi ra ngoài hoặc tiếp xúc với người khác. • Hạn chế tụ tập đông người và giữ khoảng cách với những người có triệu chứng bệnh. • Cải thiện sức khỏe bằng cách ăn uống đủ chất, ngủ đủ giấc, và tập thể dục nhẹ nhàng."}, {"u": "./chapter_3.html#chapter-3__43", "c": "Chương 3", "k": "3", "n": 90, "q": "Khu trọ tôi ở bị ngập úng do mưa lớn và luôn bị ảnh hưởng của mưa, bão khiến cuộc sống sinh hoạt thường ngày gặp rất nhiều khó khăn. Tôi phải làm gì để bảo vệ sức khỏe và đảm bảo an toàn?", "a": "- Ngập úng và mưa bão có thể gây ra các bệnh liên quan đến môi trường ẩm ướt, như bệnh da liễu hoặc bệnh truyền nhiễm. - Việc ứ đọng nước thường xuyên tạo điều kiện cho muỗi sinh sôi và làm tăng nguy cơ mắc các bệnh nguy hiểm như sốt xuất huyết. - Bạn nên: • Sử dụng các biện pháp chống thấm nếu có thể. • Giữ vệ sinh khu vực sinh sống và đảm bảo không để nước ngập lâu trong phòng. • Chuẩn bị đồ bảo hộ (ủng, áo mưa) và thuốc men dự phòng cho những ngày mưa bão kéo dài. • Nếu tình trạng quá nghiêm trọng, bạn nên cân nhắc chuyển đến khu vực ít bị ngập lụt do mưa bão."}, {"u": "./chapter_3.html#chapter-3__44", "c": "Chương 3", "k": "3", "n": 91, "q": "Khu trọ tôi thuê ở xa bệnh viện, hoàn cảnh gia đình tôi rất khó khăn. Nếu bị bệnh, tôi phải làm thế nào?", "a": "• Khi sống ở xa bệnh viện, bạn có thể gặp khó khăn khi cần chăm sóc y tế khẩn cấp. • Để chủ động bảo vệ sức khỏe bạn nên: • Tìm hiểu các phòng khám gần nhà có thể cung cấp dịch vụ sơ cứu hoặc điều trị cơ bản. • Sử dụng dịch vụ bảo hiểm y tế để được hỗ trợ chi phí điều trị khi cần thiết. • Dự trữ thuốc men cơ bản tại nhà để điều trị các bệnh thông thường. • Nếu bạn gặp vấn đề sức khỏe nghiêm trọng, bạn nên liên hệ với đồng nghiệp, người thân, bạn bè, chính quyền địa phương hoặc các tổ chức từ thiện để được hỗ trợ."}, {"u": "./chapter_4.html#chapter-4__1", "c": "Chương 4", "k": "4", "n": 92, "q": "Làm sao tôi biết mình có thể đang mắc các bệnh truyền nhiễm? Những biểu hiện đặc trưng của loại bệnh này là gì?", "a": "• Biểu hiện đặc trưng của các bệnh truyền nhiễm bao gồm: sốt cao, ớn lạnh. Tuỳ theo từng loại nhiễm trùng có thể bị ho, khó thở, chán ăn, tiêu chảy, tiểu buốt, tiểu giắt… • Nếu bạn bị bệnh truyền nhiễm hô hấp, ngoài sốt cao và ho bạn còn thấy đau họng, sổ mũi, có thể đau tức ngực,... • Nếu bị bệnh truyền nhiễm da, bạn có thể thấy da bị lở loét, mẩn đỏ, mọc mụn…. • Nếu bị bệnh truyền nhiễm tiêu hóa, ngoài sốt cao, bạn có thể bị đau bụng, đi ngoài nhiều lần, buồn nôn, nôn…."}, {"u": "./chapter_4.html#chapter-4__2", "c": "Chương 4", "k": "4", "n": 93, "q": "Tôi bị ho và sốt, có phải tôi bị nhiễm trùng hô hấp không? Tôi có cần sử dụng thuốc kháng sinh không?", "a": "- Khi bạn bị ho, sốt, khả năng bạn bị nhiễm trùng hô hấp (họng, phế quản hoặc phổi…). - Việc điều trị bệnh viêm hô hấp nói chung hay uống thuốc kháng sinh là do bác sĩ khám và chỉ định. - Nhiễm trùng hô hấp có thể do nhiều nguyên nhân, vì vậy mỗi trường hợp sẽ có cách điều trị khác nhau, không phải lúc nào cũng cần dùng thuốc kháng sinh. Nhiều người đã lạm dụng thuốc kháng sinh bằng cách tự mua thuốc uống khi thấy mình bị sốt và đau họng. Việc này tiềm ẩn nhiều rủi ro, như điều trị không đúng nguyên nhân và làm vi khuẩn kháng (nhờn) với thuốc kháng sinh, khiến việc điều trị sau này khó khăn hơn."}, {"u": "./chapter_4.html#chapter-4__3", "c": "Chương 4", "k": "4", "n": 94, "q": "Nếu bị nhiễm trùng hô hấp, tôi nên đi khám ở đâu?", "a": "• Bạn nên đi khám ở cơ sở y tế gần nhất. Tuỳ theo quy mô của cơ sở y tế mà bạn sẽ được hướng dẫn khám ở khoa khám bệnh phù hợp. • Nếu bạn bị bệnh nặng, có thể được chuyển lên các bệnh viện tuyến trên hoặc bệnh viện chuyên khoa. Bảng 4.1 Giới thiệu tóm tắt về các loại bệnh truyền nhiễm phổ biến hay gặp ở Việt Nam: - Bệnh truyền nhiễm hay còn gọi là bệnh lây nhiễm, gây ra bởi các mầm bệnh là virus, vi khuẩn, nấm…, xâm nhập vào cơ thể từ bên ngoài. Bệnh cúm, sởi, COVID-19,… đều là những bệnh truyền nhiễm phổ biến. Một số bệnh thường gặp và dễ lây truyền từ người này sang người khác như: Cúm, thuỷ đậu, HIV, HPV, Lao, Covid-19, sốt xuất huyết, quai bị, sởi, bạch hầu… - Các bệnh truyền nhiễm trên thế giới đang có xu hướng diễn biến phức tạp, đặc biệt là khi thời tiết liên tục diễn biến cực đoan, ô nhiễm môi trường ngày càng nghiêm trọng khiến điều kiện sống của con người xuất hiện nhiều tác nhân tiêu cực, virus, vi khuẩn có thể lây lan nhanh chóng. - Bệnh truyền nhiễm thường có các đặc điểm chung như sau: • Tác nhân gây bệnh: Do một hoặc nhiều mầm bệnh gây ra, có thể là virus, vi khuẩn, ký sinh trùng, nấm… lây lan từ người qua người hoặc từ động vật qua người. • Giai đoạn ủ bệnh: Thời gian ủ bệnh thường chưa xuất hiện triệu chứng, thời gian ủ bệnh chủ yếu phụ thuộc vào độc tính của mầm bệnh và sức đề kháng của cơ thể mỗi người. • Khả năng lây nhiễm: Bệnh truyền nhiễm dễ dàng lây lan từ người sang người (đường máu, hô hấp, quan hệ tình dục, từ mẹ sang con…) hoặc từ vật sang người (vết côn trùng cắn,…) • Biểu hiện: Đa số các bệnh truyền nhiễm thường có biểu hiện chung như: sốt cao, ho, ớn lạnh, chán ăn, tiêu chảy,… • Khả năng bùng phát thành dịch: Khi không có biện pháp kiểm soát và phòng ngừa kịp thời, bệnh có thể bùng phát thành dịch. • Khả năng điều trị: Các bệnh truyền nhiễm đa số có thể chữa khỏi nếu phát hiện và điều trị kịp thời. Tuy nhiên, một số bệnh truyền nhiễm nguy hiểm có diễn biến bệnh rất nhanh, khiến người bệnh trở năng hoặc tử vong khi chưa kịp chẩn đoán bệnh. • Gây ảnh hưởng sức khỏe cộng đồng: Bệnh truyền nhiễm có khả năng lây lan nhanh gây ảnh hưởng đến sức khỏe của cộng đồng, gây áp lực lên hệ thống y tế tại địa phương. • Bệnh truyền nhiễm có thể được phòng ngừa và kiểm soát bằng nhiều biện pháp khác nhau."}, {"u": "./chapter_4.html#chapter-4__4", "c": "Chương 4", "k": "4", "n": 95, "q": "Gia đình tôi có con bị sốt xuất huyết. Tôi nên làm gì?", "a": "• Trước hết, bạn cần xác định chắc chắn rằng con bạn bị sốt xuất huyết thông qua xét nghiệm và chẩn đoán bởi nhân viên y tế hoặc cơ sở y tế. • Sau khi được chẩn đoán là sốt xuất huyết, gia đình bạn cần tuân thủ đúng hướng dẫn điều trị và chăm sóc của nhân viên y tế. • Thực hiện các biện pháp phòng lây bệnh bằng cách cả gia đình đều tránh bị muỗi đốt (ngủ màn, mặc quần áo dài, dùng kem hoặc bình xịt chống muỗi). • Vệ sinh hoặc làm sạch các dụng cụ chứa nước tù đọng và phát quang các bụi rậm quanh nhà để muỗi không sinh sôi."}, {"u": "./chapter_4.html#chapter-4__5", "c": "Chương 4", "k": "4", "n": 96, "q": "Tôi cần làm gì để phòng tránh bệnh sốt xuất huyết cho gia đình?", "a": "• Giữ môi trường sạch sẽ, phát quang bụi rậm, không để nước đọng lâu ngày để hạn chế muỗi sinh sôi nảy nở. • Tránh bị muỗi đốt bằng cách ngủ màn, mặc quần áo kín khi học tập hoặc làm việc. • Có thể sử dụng một số thuốc chống muỗi (kem bôi, thuốc xịt) theo hướng dẫn. Bảng 4.2 HƯỚNG DẪN PHÒNG NGỪA BỆNH TRUYỀN NHIỄM Để giảm nguy cơ mắc bệnh truyền nhiêm, bạn cần biết cách để phòng ngừa. Một số phương pháp giúp phòng ngừa bệnh lây nhiễm hiệu quả bao gồm: Tiêm vắc-xin phòng bệnh • Vắc-xin là phương pháp đơn giản, an toàn, tiết kiệm và hiệu quả nhất có thể làm giảm nguy cơ mắc bệnh bằng cách tăng cường hệ thống miễn dịch của cơ thể chống lại sự lây nhiễm từ tác nhân gây bệnh. Các bệnh lây truyền có thể phòng ngừa bằng vắc-xin như: lao, bạch hầu, uốn ván, thương hàn, sởi, rubella, thủy đậu, viêm gan virus, viêm não Nhật Bản,… Hiện có khoảng 50 loại vắc-xin cho các lứa tuổi khác nhau và các loại bệnh khác nhau. Vệ sinh cá nhân thường xuyên • Vệ sinh cá nhân thường xuyên giúp hạn chế tối đa nguy cơ nhiễm bệnh. Cụ thể, bạn cần rửa tay sạch sẽ bằng xà phòng, dung dịch sát khuẩn tay thường xuyên vào thời điểm trước khi ăn, sau khi đi vệ sinh, sau khi ho, hắt hơi, sau khi tiếp xúc với bề mặt ẩm ướt, tiếp xúc với thú cưng,… Bên cạnh đó, để tránh nguy cơ vi khuẩn, virus xâm nhập vào cơ thể, bạn cần lưu ý không chạm tay lên mắt, mũi, cho tay vào miệng,… Vệ sinh và an toàn thực phẩm • Một trong những nguy cơ làm tăng khả năng lây nhiễm bệnh đó là sử dụng thực phẩm không an toàn. Do đó, để ngăn mầm bệnh xâm nhập, bạn nên ăn chín uống sôi, không sử dụng thực phẩm không rõ nguồn gốc xuất xứ,… Đồng thời, dụng cụ nấu ăn, bếp nên được vệ sinh sạch sẽ trước khi chế biến thực phẩm để hạn chế nguy cơ lây nhiễm gián tiếp mầm bệnh. Sinh hoạt tình dục an toàn • Sinh hoạt tình dục an toàn là cách để phòng ngừa các bệnh lây truyền qua đường tình dục như lậu, giang mai, HIV,… Vì vậy, hãy luôn sử dụng bao cao su khi quan hệ tình dục với bạn tình, đặc biệt người có nguy cơ cao mắc bệnh lây truyền qua đường tình dục. Đồng thời, nên hạn chế quan hệ với nhiều bạn tình, để tránh nguy cơ mắc bệnh truyền nhiễm qua đường tình dục. Phòng ngừa bệnh lây truyền từ côn trùng và động vật • Côn trùng là nguồn phát bệnh lây truyền nhanh chóng. Vì vậy, để tránh nguy cơ mắc bệnh, mỗi cá nhân, gia đình cần phòng tránh côn trùng truyền bệnh bằng cách sử dụng màn ngủ, hương xua, kem thoa, thuốc xịt côn trùng... Giữ môi trường sống sạch sẽ • Giữ gìn vệ sinh sạch sẽ, khử trùng môi trường xung quanh một cách thường xuyên để phòng tránh bệnh. Theo đó, khu vực phòng ngủ, phòng khách, sân vườn,… nên được quét dọn hàng ngày."}, {"u": "./chapter_4.html#chapter-4__6", "c": "Chương 4", "k": "4", "n": 97, "q": "Bệnh lao có biểu hiện như thế nào?", "a": "• Bệnh lao có biểu hiện đặc trưng là: sốt về chiều, cơ thể mệt mỏi, gầy sút, ho khan hoặc ho có đờm kéo dài trong vài tuần (trường hợp nặng có thể ho ra máu). Một số người có kèm theo đau ngực. • Biểu hiện này rất dễ nhầm với biểu hiện của một số bệnh khác hoặc suy nhược cơ thể do nhiều nguyên nhân khác nhau."}, {"u": "./chapter_4.html#chapter-4__7", "c": "Chương 4", "k": "4", "n": 98, "q": "Tôi có thể đi khám và làm xét nghiệm bệnh lao ở đâu?", "a": "• Nếu có các biểu hiện trên, bạn nên đến bệnh viện hoặc các cơ sở y tế khám và làm các xét nghiệm cần thiết nhằm chẩn đoán chính xác. • Bạn nên đi khám tại cơ sở y tế (tốt nhất là đến Bệnh viện Phổi Trung ương, hoặc Khoa Hô hấp tại các bệnh viện…), để được khám và làm xét nghiệm."}, {"u": "./chapter_4.html#chapter-4__8", "c": "Chương 4", "k": "4", "n": 99, "q": "Nếu tôi được chẩn đoán là bị mắc bệnh lao, tôi có thể tự mua thuốc điều trị được không?", "a": "• Nếu bạn bị bệnh lao, bạn không thể tự điều trị. Bệnh lao là bệnh truyền nhiễm nhưng cần thời gian điều trị bằng các loại thuốc kháng sinh lâu hơn các loại bệnh truyền nhiễm khác và dưới sự hướng dẫn, giám sát của nhân viên y tế. • Nếu đúng bị bệnh lao, bạn sẽ cần điều trị trong một thời gian dài, tuỳ theo thể bệnh (có thể 3-9 tháng). • Với bệnh lao, bạn cần kiên trì và tuân thủ điều trị. • Trong thời gian điều trị lao, nếu sức khoẻ của bạn cảm thấy ổn, bạn vẫn có thể đi làm theo hướng dẫn của bác sĩ."}, {"u": "./chapter_4.html#chapter-4__9", "c": "Chương 4", "k": "4", "n": 100, "q": "Tôi vừa bị chó lạ cắn khi đang trên đường đi làm về. Tôi có nguy cơ bị mắc bệnh dại không? Tôi cần làm gì để xử lý và phòng ngừa tạm thời?", "a": "Khi bị chó cắn, bạn có thể bị mắc bệnh dại nếu con chó bị dại. • Bạn cần rửa sạch vết cắn với xà phòng hoặc muối loãng để giảm nguy cơ nhiễm bệnh và đi đến cơ sở y tế càng sớm càng tốt để được khám và theo dõi. Đồng thời, bạn nên yêu cầu người chủ chó giữ con chó ít nhất 10 ngày để theo dõi xem có bị dại không. • Bạn có thể yêu cầu tiêm vắc-xin dại ngay mà không cần chờ theo dõi nếu chó có biểu hiện dại ngay sau khi cắn bạn, hoặc chó lạ sau khi cắn bạn xong chạy mất không theo dõi được. • Khi bị chó cắn, tuyệt đối không được chủ quan không đi khám và tiêm phòng vì nếu con chó mang virus dại, bạn có nguy cơ mắc bệnh dại – một bệnh rất nguy hiểm và hầu như không thể cứu chữa khi đã phát bệnh. Vì vậy, cần tiêm vắc-xin phòng dại càng sớm càng tốt."}, {"u": "./chapter_4.html#chapter-4__10", "c": "Chương 4", "k": "4", "n": 101, "q": "Tôi bị chó cắn, có thể chữa chó dại cắn bằng thuốc đông y không? Tôi nghe nhiều người nói, tiêm vắc-xin phòng dại rất hại sức khỏe?", "a": "• Bị chó dại cắn không thể chữa khỏi bằng thuốc đông y, nhiều người không đi tiêm phòng dại và tự điều trị bằng các loại thuốc nam, đã bị tử vong. • Tiêm vắc-xin sau khi bị chó cắn là rất quan trọng, không có loại thuốc đông y nào chữa được bệnh dại."}, {"u": "./chapter_4.html#chapter-4__11", "c": "Chương 4", "k": "4", "n": 102, "q": "Tôi và mấy người bạn đi nhậu (lòng lợn, tiết canh). Sau khi ăn xong về, ba trong sáu người chúng tôi bị đau bụng, tiêu chảy nặng. Có phải chúng tôi bị đau bụng đi ngoài là do ăn tiết canh không? Chúng tôi phải làm gì?", "a": "• Khả năng rất cao (gần như chắc chắn) là bạn đã bị đau bụng đi ngoài do ăn tiết canh. • Trước tiên, bạn nên nằm nghỉ ngơi, uống nhiều nước và bổ sung các loại bù nước điện giải cho đi ngoài mất nước như nước gạo rang. • Sau đó cần đến cơ sở y tế gần nhất để khám bệnh và được cho thuốc uống. LƯU Ý : Bạn không nên ăn tiết canh (máu sống) của bất kỳ con vật nào, vì nguy cơ nhiễm bệnh rất cao."}, {"u": "./chapter_4.html#chapter-4__12", "c": "Chương 4", "k": "4", "n": 103, "q": "Anh Thọ 35 tuổi đến từ tỉnh Ninh Bình và đã kết hôn, hỏi: Sau nhiều năm làm việc tại một công ty, tôi vừa bị mất việc nên tâm trạng bất ổn. Tôi thường rủ bạn bè đi uống rượu để giải khuây. Sau khi uống rượu tôi cảm thấy tốt hơn, thậm chí nếu một ngày không uống rượu, tâm trạng của tôi lại trở nên tồi tệ. Trong trường hợp này, tôi nên làm gì?", "a": "• Trước hết anh nên tìm một công việc khác phù hợp hơn. • Trong thời gian rảnh, anh nên tham gia các hoạt động thể dục thể thao để giúp cân bằng cảm xúc. • Dành nhiều thời gian kết nối với người thân, bạn bè. • Anh có thể tham khảo thêm những ảnh hưởng tiêu cực khi dùng bia rượu quá nhiều dưới đây để thấy nguy cơ mắc các bệnh khi uống rượu thường xuyên: • Tăng mỡ xấu trong cơ thể. • Gây xơ gan, sử dụng lâu ngày làm nguy cơ gan nhiễm mỡ, viêm gan mạn tính, ung thư gan. • Làm tăng lượng đường trong máu • Làm ảnh hướng đến hệ thần kinh, gây tổn thương não, • Suy giảm ham muốn tình dục và giảm chất lượng sinh sản."}, {"u": "./chapter_4.html#chapter-4__13", "c": "Chương 4", "k": "4", "n": 104, "q": "Anh Đạt 25 tuổi hỏi: Trước đây tôi chưa từng hút thuốc lá. Sau khi vào làm việc cho một công ty tại thành phố Đồng Nai, các bạn đồng nghiệp của tôi đã hút thuốc và đưa cho tôi hút thử. Sau khi hút thuốc, tâm trạng của tôi bớt căng thẳng, từ đó tôi thường xuyên sử dụng thuốc lá và ngày một nhiều lên. Như vậy có hại đến sức khoẻ không?", "a": "Hút thuốc lá rất có hại cho sức khỏe vì vậy anh nên tìm mọi cách bỏ hẳn hút thuốc. Tác hại cụ thể: • Hút thuốc lá gây tổn thương phổi, dẫn đến suy hô hấp mạn tính. • Nguy cơ mắc các bệnh về hô hấp, đặc biệt là ung thư phổi. • Hút thuốc làm tăng nguy cơ mắc các bệnh lý tim mạch và đột quỵ gấp nhiều lần."}, {"u": "./chapter_4.html#chapter-4__14", "c": "Chương 4", "k": "4", "n": 105, "q": "Tôi nên làm gì để giảm hút thuốc lá?", "a": "• Anh nên làm mọi cách để dừng hút thuốc lá (cai nghiện thuốc lá). • Anh có thể tham khảo một số hướng dẫn để cai thuốc lá ở Bảng 4.4 dưới đây: Bảng 4.4 MỘT SỐ HƯỚNG DẪN ĐỂ CAI THUỐC LÁ Những việc cần làm để giảm thói Thay thế sang một loại sản phẩm quen hút thuốc lá: khác làm giảm quá trình thèm Loại bỏ tất cả thuốc lá, gạt tàn, diêm hút thuốc: và bật lửa khỏi nhà, văn phòng và xe Miếng dán nicotine: Bạn dán trực hơi của bạn. tiếp lên da mỗi ngày một lần và chỉ nên sử dụng vào ban ngày. Thay đổi thói quen, cố gắng tránh những người hoặc tình huống khiến Viên ngậm nicotine: Điều trị thường bạn muốn hút thuốc. kéo dài khoảng 12 tuần. Sau 1-2 giờ sẽ ngậm 1 viên trong 6 tuần đầu Hãy nói với mọi người xung quanh là tiên, 2-4 giờ/1 viên trong tuần thứ 7 - bạn đang cai thuốc. 9 và cứ sau 4-8 giờ trong tuần thứ Dành thời gian làm các hoạt động thư 10-12. giãn, tập thể dục để giảm căng thẳng Thuốc xịt mũi nicotine: Loại xịt này và tránh các cơn thèm thuốc. chỉ bán theo đơn của bác sĩ. Thuốc Dành nhiều thời gian ở những nơi xịt cung cấp nicotine vào máu của không cho phép hút thuốc. bạn một cách nhanh chóng bằng Sử dụng đồ ăn nhẹ ít calo khi bạn có cách xịt vào mỗi mũi với liều dùng triệu chứng thèm thuốc lá. thường là một hoặc hai lần mỗi giờ theo hướng dẫn. Hiện nay, trên thị trường có nhiều loại sản phẩm thuốc lá khác nhau, Thuốc hít nicotine: Thuốc này cũng bao gồm thuốc lá điếu truyền thống, được bán theo đơn của bác sĩ. Chất thuốc lá điện tử và các sản phẩm nicotine được giải phóng từ ống hít thuốc lá nung nóng. Tuy nhiên, thuốc vào trong miệng giúp giảm cảm giác lá điện tử, thuốc lá nung nóng và các thèm thuốc. sản phẩm vape đều là những mặt Kẹo cao su nicotine: Một hộp 48 hàng bị cấm tại Việt Nam. Dù ở dạng miếng và bạn nhai một miếng kẹo nào, chúng đều tiềm ẩn nguy cơ ảnh cao su sau 1 - 2 giờ, nhưng không hưởng tới sức khỏe của bạn và những quá 24 miếng mỗi ngày. người xung quanh. Vì vậy, việc nên làm là chấm dứt hút thuốc lá càng sớm càng tốt."}, {"u": "./chapter_4.html#chapter-4__15", "c": "Chương 4", "k": "4", "n": 106, "q": "Sau giờ làm, tôi thường đến các quán bar, câu lạc bộ để gặp gỡ bạn bè. Một số bạn bè của tôi đã dùng ma túy và nhiều lần rủ rê tôi thử. Từ chối mãi tôi cảm thấy ngại, thậm chí tôi còn bị bạn bè nói là \"khác người\" và có nguy cơ bị tẩy chay. Tôi nên làm gì?", "a": "• Bạn từ chối là đúng, bạn không cần cảm thấy mình “khác biệt” theo hướng tiêu cực như bạn bè nghĩ. Vì việc sử dụng ma túy là vi phạm pháp luật theo Luật Phòng, chống ma túy 2021. • Tìm nhóm bạn mới tích cực là những người thân thiện, không dùng ma túy và chia sẻ hoạt động lành mạnh (thể dục, nghệ thuật, đọc sách,...). • Nếu bạn cảm thấy bị cô lập, bị tổn thương tâm lý vì bị tẩy chay, nên gặp chuyên gia tâm lý hoặc tư vấn sức khỏe tâm thần để xử lý áp lực nội tâm. • Hãy gần gũi hơn với gia đình và người thân."}, {"u": "./chapter_4.html#chapter-4__16", "c": "Chương 4", "k": "4", "n": 107, "q": "Tôi đã có bạn gái ở quê, nhưng gần đây đã phát sinh quan hệ tình dục với gái mại dâm. Sau đó, tôi cảm thấy rất lo lắng. Tôi nên làm gì?", "a": "• Để đảm bảo an toàn sức khỏe, bạn nên đến các cơ sở y tế có uy tín và có chuyên môn để được tư vấn, xát nghiệm và dự phòng các bệnh lây truyền qua đường tình dục. Đồng thời, chấm dứt hành vi quan hệ tình dục với gái mại dâm. • Đặc biệt, nên sử dụng bao cao su khi quan hệ tình dục và duy trì chung thủy với một bạn tình. Việc quan hệ với gái mại dâm tiềm ẩn nguy cơ rất cao lây nhiễm các bệnh qua đường tình dục."}, {"u": "./chapter_4.html#chapter-4__17", "c": "Chương 4", "k": "4", "n": 108, "q": "Gần đây, đồng nghiệp của tôi kiếm được khá nhiều tiền từ việc đánh bạc qua các ứng dụng trên điện thoại. Điều này khiến tôi nảy sinh suy nghĩ muốn thử để “đổi đời”. Tôi có nên chơi thử không?", "a": "• Ở Việt Nam, hầu hết hình thức đánh bạc trực tuyến là trái phép và có thể bị xử phạt hình sự. Đồng thời, tỷ lệ nghiện cờ bạc dẫn đến nợ nần và khủng hoảng tài chính rất cao. Vì vậy, bạn không nên tham gia để tránh rủi ro về pháp lý và tài chính. • Nếu bạn cảm thấy bị áp lực hay tò mò, nên tìm hoạt động khác tích cực như: Học tập, rèn luyện thể thao hoặc phát triển các kỹ năng cá nhân."}];
